insert into woerter (slug, wort, artikel, ipa, wortart, kategorie, definition, bedeutungen, beispiel) values
  ('mueuevabrennungsaunlog-schbittelau', 'Müüvabrennungsaunlog Schbittelau', '', '', '', '', 'Müllverbrennungsanlage Spittelau', '[{"kategorie": "allg.", "text": "bedeutende und markante Müllverwertungsanlage im 9. Wiener Gemeindebezirk ([[Alsergrund]])"}, {"kategorie": "", "text": "Sie ist eines der bekanntesten Bauwerke der Stadt und wurde durch den berühmten österreichischen Künstler und Architekten Friedensreich Hundertwasser neu gestaltet"}, {"kategorie": "", "text": "Die Müllverbrennungsanlage Spittelau wurde ursprünglich 1969 bis 1971 gebaut, um den Abfall der Stadt Wien zu verwerten und gleichzeitig Energie in Form von Fernwärme und Strom zu gewinnen. In ihrer ersten Phase war die Anlage rein funktional und utilitaristisch gestaltet, typisch für industrielle Bauten dieser Zeit"}, {"kategorie": "", "text": "Im Jahr 1987 wurde die Anlage durch einen Brand schwer beschädigt. Anstatt die Anlage abzureißen oder schlicht wieder aufzubauen, entschied sich die Stadt Wien, die Müllverbrennungsanlage als Pilotprojekt für eine umweltfreundlichere und ästhetisch ansprechendere Müllverwertungseinrichtung zu rekonstruieren. Der Künstler Friedensreich Hundertwasser, bekannt für seine organischen Formen und farbenfrohen Designs, wurde beauftragt, die Außenfassade der Anlage zu gestalten. Die Wiedereröffnung der neugestalteten Anlage fand 1992 statt"}, {"kategorie": "", "text": "Die Müllverbrennungsanlage Spittelau ist ein herausragendes Beispiel für die Verbindung von Funktionalität und Kunst. Hundertwassers Gestaltung machte die Anlage zu einem ikonischen Bauwerk in Wien. Typisch für Hundertwassers Stil sind die unregelmäßigen, fließenden Formen, die bunten Mosaike, die goldene Kuppel sowie die grünen, bewachsenen Dachflächen. Diese Gestaltungselemente verleihen der Anlage eine einzigartige Erscheinung, die sie deutlich von herkömmlichen Industriegebäuden unterscheidet."}]'::jsonb, ''),
  ('matzleinsduafa-plotz', 'Matzleinsduafa Plotz', '', '', '', '', 'Matzleinsdorfer Platz', '[{"kategorie": "allg.", "text": "wichtiger Verkehrsknotenpunkt im 5. Wiener Gemeindebezirk ([[Margareten]]) und im 10. Bezirk ([[Favoriten]])"}, {"kategorie": "", "text": "Er ist bekannt für seine zentrale Rolle im öffentlichen Nahverkehr Wiens, insbesondere als Schnittstelle für verschiedene Straßenbahn- und S-Bahn-Linien"}, {"kategorie": "", "text": "Der Matzleinsdorfer Platz ist außerdem von historischen und modernen Gebäuden umgeben und spielt eine wichtige Rolle im städtischen Leben"}, {"kategorie": "", "text": "Der Matzleinsdorfer Platz erhielt seinen Namen von dem historischen Stadtteil [[Matzleinsdorf]], der im Mittelalter als eigenständiges Dorf existierte und später nach Wien eingemeindet wurde. Im Laufe des 19. und frühen 20. Jahrhunderts entwickelte sich das Gebiet um den Platz herum zu einem dicht bebauten städtischen Viertel"}, {"kategorie": "", "text": "Im 19. Jahrhundert war der Matzleinsdorfer Platz ein wichtiger Bahnknotenpunkt für die Südbahnstrecke, die Wien mit dem Süden Österreichs verband. Der Platz und die Umgebung wurden zunehmend urbanisiert, und es entstanden zahlreiche Wohnhäuser, Geschäfte und Gewerbebetriebe"}]'::jsonb, ''),
  ('evangelischa-friidhof-matzleinsduaf', 'Evangelischa Friidhof Matzleinsduaf', '', '', '', '', 'Evangelischer Friedhof Matzleinsdorf', '[{"kategorie": "allg.", "text": "bedeutender historischer Friedhof in Wien, der im 10. Wiener Gemeindebezirk ([[Favoriten]]) liegt"}, {"kategorie": "", "text": "Er ist einer der ältesten evangelischen Friedhöfe in Wien und hat eine besondere Bedeutung für die evangelische Gemeinschaft der Stadt. Der Friedhof ist bekannt für seine historischen Gräber, seine ruhige Atmosphäre und seine Rolle als wichtiger Erinnerungsort für die protestantische Geschichte Wiens"}, {"kategorie": "", "text": "Der Evangelische Friedhof Matzleinsdorf wurde im Jahr 1858 eröffnet, zu einer Zeit, als die evangelische Gemeinde in Wien zu wachsen begann und einen eigenen Begräbnisort benötigte. Vor der Errichtung dieses Friedhofs war es den evangelischen Christen in Wien oft nur unter schwierigen Bedingungen möglich, ihre Verstorbenen zu bestatten, da sie von den katholischen Friedhöfen ausgeschlossen waren oder nur in speziell zugewiesenen Bereichen begraben werden durften"}, {"kategorie": "", "text": "Mit der Eröffnung des Evangelischen Friedhofs Matzleinsdorf bekamen die evangelischen Gemeinden der Stadt endlich einen eigenen Friedhof, der ihren religiösen Bedürfnissen und Bräuchen entsprach. Der Friedhof wurde in den folgenden Jahrzehnten kontinuierlich erweitert und entwickelte sich zu einem zentralen Begräbnisort für viele prominente Wiener Protestanten (z.B. Marie von Ebner-Eschenbach, Carl Ritter von Ghega, Ludwig Anzengruber)"}, {"kategorie": "", "text": "Besonders bemerkenswert ist die Friedhofskapelle, die als zentraler Ort für Trauerfeiern und Gedenkveranstaltungen dient. Die Kapelle wurde in einem schlichten, funktionalen Stil errichtet, der die protestantische Tradition der Zurückhaltung und Einfachheit widerspiegelt."}]'::jsonb, ''),
  ('matzleinsduafa-pfoakiachn', 'Matzleinsduafa Pfoakiachn', '', '', '', '', 'Matzleinsdorfer Pfarrkirche', '[{"kategorie": "allg.", "text": "\"bedeutende römisch-katholische Kirche im 5. Wiener Gemeindebezirk ([[Margareten]]), auch bekannt als \"Pfarrkirche zur Heiligen Maria Magdalena\""}, {"kategorie": "", "text": "Die Matzleinsdorfer Pfarrkirche wurde im 19. Jahrhundert erbaut, die Grundsteinlegung erfolgte im Jahr 1846, und die Kirche wurde nach Plänen des Architekten Matthias Schönerer errichtet. Die Einweihung der Kirche fand 1848 statt"}, {"kategorie": "", "text": "Die Matzleinsdorfer Pfarrkirche ist ein Beispiel für die [[neugotische]] Architektur des 19. Jahrhunderts. Die Kirche zeichnet sich durch ihre schlanken, hoch aufragenden Formen und die Verwendung typischer gotischer Elemente wie Spitzbögen, [[Fensterrosetten]] und [[Kreuzrippengewölbe]] aus. Die Fassade der Kirche ist relativ schlicht gehalten, doch ihre architektonischen Details verleihen ihr eine beeindruckende und ehrfurchtgebietende Präsenz"}, {"kategorie": "", "text": "Das Innere der Kirche ist ebenso im neogotischen Stil gestaltet, mit einem prächtigen Hochaltar, der mit kunstvollen Schnitzereien und Gemälden verziert ist. Die Fenster der Kirche sind mit farbenfrohen Glasmalereien versehen, die Szenen aus dem Leben Jesu und der Heiligen Maria Magdalena darstellen."}]'::jsonb, ''),
  ('sankt-marx', 'Sankt Marx', '', '', '', '', 'Sankt Marx', '[{"kategorie": "allg.", "text": "\"historischer Stadtteil im 3. Wiener Gemeindebezirk ([[Landstraße]])\". Der Stadtteil ist bekannt für seine industrielle Vergangenheit, den [[Sankt]] Marxer Friedhof und das moderne Medienzentrum [[Media]] Quarter Marx"}, {"kategorie": "", "text": "Der Name \"Sankt Marx\" leitet sich von einem Hospital des Heiligen Markus (Sankt Marx) ab, das im Mittelalter in diesem Gebiet errichtet wurde. Das Hospital, das sich der Pflege von Leprakranken widmete, war eines der bekanntesten seiner Art in Wien. Der Name des Heiligen Markus (Marx) blieb im Laufe der Jahrhunderte erhalten und prägte den Stadtteil"}, {"kategorie": "", "text": "Im 19. Jahrhundert entwickelte sich Sankt Marx zu einem bedeutenden Industriegebiet. Zahlreiche Fabriken und Gewerbebetriebe siedelten sich hier an, und das Gebiet war vor allem für seine Schlachthöfe bekannt. Der Wiener Zentralviehmarkt und die Sankt Marxer Schlachthöfe spielten eine zentrale Rolle in der Versorgung der Stadt mit Fleisch und anderen landwirtschaftlichen Produkten"}, {"kategorie": "", "text": "In den letzten Jahrzehnten hat sich das Gebiet rund um Sankt Marx stark gewandelt. Viele der alten Industriebauten wurden abgerissen oder umgenutzt, und das Gebiet hat sich zu einem modernen städtischen Bereich entwickelt. Ein zentrales Element dieser Transformation ist das [[Media]] Quarter Marx, ein modernes Medien- und Technologiezentrum, das zahlreiche Unternehmen aus den Bereichen Medien, Kommunikation und Forschung beherbergt."}]'::jsonb, ''),
  ('sankt-marxa-friidhof', 'Sankt Marxa Friidhof', '', '', '', '', 'Sankt Marxer Friedhof', '[{"kategorie": "", "text": "Der Sankt Marxer Friedhof wurde im Jahr 1784 eröffnet, als Teil der Reformen von Kaiser Joseph II., der die hygienischen Bedingungen in Wien verbessern wollte. Diese Reformen führten dazu, dass Friedhöfe außerhalb der Stadtmauern angelegt wurden, um die Ausbreitung von Krankheiten zu verhindern. Der Sankt Marxer Friedhof war einer von mehreren Vorstadtfriedhöfen, die zu dieser Zeit gegründet wurden"}, {"kategorie": "", "text": "Der Friedhof wurde nach dem nahegelegenen Hospital des Heiligen Markus (Sankt Marx) benannt, das sich in diesem Gebiet befand. Ursprünglich diente der Friedhof als Begräbnisstätte für die ärmeren Bevölkerungsschichten, aber auch viele bedeutende Persönlichkeiten Wiens fanden hier ihre letzte Ruhe"}, {"kategorie": "", "text": "Wolfgang Amadeus Mozart wurde 1791 in einem einfachen Schachtgrab auf dem Sankt Marxer Friedhof beigesetzt. Da es zu dieser Zeit üblich war, Verstorbene in anonymen Gemeinschaftsgräbern zu bestatten, ist die genaue Lage von Mozarts Grab bis heute nicht eindeutig geklärt. Ein Gedenkstein und ein Kenotaph wurden jedoch später errichtet, um an ihn zu erinnern"}, {"kategorie": "", "text": "Der Sankt Marxer Friedhof ist im Stil eines klassischen Vorstadtfriedhofs des 18. und 19. Jahrhunderts gestaltet. Er erstreckt sich über eine Fläche von etwa 60.000 Quadratmetern und ist von einer hohen Mauer umgeben, die den Friedhof von der Umgebung abschirmt. Die Anlage ist durch schmale Wege, alte Bäume und zahlreiche Grabsteine und Denkmäler geprägt, die das historische Ambiente des Friedhofs unterstreichen"}, {"kategorie": "", "text": "Viele der Grabsteine und Monumente sind kunstvoll gestaltet und tragen Inschriften, die an die Verstorbenen erinnern. Besonders bemerkenswert sind die Grabmäler bedeutender Persönlichkeiten, die den Friedhof zu einem wichtigen Ort der Erinnerung machen (Joseph Strauß, Michael Haydn, Carl Maria von Weber, Franz Grillparzer, Joseph Emanuel Fischer von Erlach)."}]'::jsonb, ''),
  ('media-quarter-marx', 'Media Quarter Marx', '', '', '', '', 'Media Quarter Marx', '[{"kategorie": "allg.", "text": "\"modernes Medien- und Technologiezentrum im 3. Wiener Gemeindebezirk ([[Landstraße]])\""}, {"kategorie": "", "text": "Es befindet sich im Stadtteil [[Sankt]] Marx und hat sich zu einem bedeutenden Standort für Unternehmen aus den Bereichen Medien, Kommunikation, Kreativwirtschaft und Technologie entwickelt. Das Areal steht für die erfolgreiche Transformation eines ehemaligen Industriegebiets in ein modernes urbanes Zentrum für Innovation und Kreativität"}, {"kategorie": "", "text": "Das Media Quarter Marx entstand im Rahmen der städtischen Entwicklung und Umstrukturierung des ehemaligen Industriegebiets rund um Sankt Marx. Früher war dieses Gebiet stark durch die Schlachthöfe und den Zentralviehmarkt geprägt, die eine zentrale Rolle in der Versorgung Wiens spielten. Mit dem Rückgang der Industrieproduktion und der Schließung der Schlachthöfe in den späten 20. und frühen 21. Jahrhundert wurde das Gebiet für neue Nutzungen erschlossen"}, {"kategorie": "", "text": "Das Konzept des Media Quarter Marx wurde in den 2000er Jahren entwickelt, um den Standort zu revitalisieren und ihn als modernen Hub für Medien- und Kreativunternehmen zu etablieren. Die Entwicklung des Areals wurde von der Stadt Wien stark gefördert, um den Strukturwandel zu unterstützen und den Standort attraktiv für innovative Unternehmen zu machen"}, {"kategorie": "", "text": "Das Media Quarter Marx hat sich zu einem zentralen Knotenpunkt für die Medien- und Kreativwirtschaft in Wien entwickelt. Es beherbergt eine Vielzahl von Unternehmen, die in den Bereichen Fernsehen, Filmproduktion, digitale Medien, Marketing, PR und andere kreative Dienstleistungen tätig sind"}, {"kategorie": "", "text": "Heute ist das Media Quarter Marx ein Symbol für die erfolgreiche Neugestaltung urbaner Räume in Wien. Es steht für Innovation, Kreativität und die zukunftsorientierte Ausrichtung der Stadt, insbesondere im Bereich der Medien- und Technologiebranche. Das Areal zieht eine dynamische und kreative Gemeinschaft von Fachleuten und Unternehmen an, die von der modernen Infrastruktur und den vielfältigen Möglichkeiten des Standorts profitieren."}]'::jsonb, ''),
  ('sankt-nikolaus-kiachn', 'Sankt Nikolaus Kiachn', '', '', '', '', 'Sankt Nikolaus Kirche', '[{"kategorie": "allg.", "text": "\"römisch-katholische Kirche in [[Erdberg]] 3. Wiener Gemeindebezirk ([[Landstraße]])\""}, {"kategorie": "", "text": "Sie ist dem heiligen Nikolaus von Myra geweiht, einem der am weitesten verehrten Heiligen in der christlichen Tradition, der besonders als Schutzpatron der Kinder und Seefahrer bekannt ist"}, {"kategorie": "", "text": "Die Ursprünge der Kirche gehen auf das Jahr 1668 zurück, als mit dem Bau begonnen wurde. Sie wurde im Jahr 1678 geweiht"}, {"kategorie": "", "text": "Die Sankt Nikolaus Kirche ist im Barockstil errichtet, einem Baustil, der für seine üppigen Verzierungen, prunkvollen Altäre und kunstvoll gestalteten Deckenfresken bekannt ist. Die Kirche zeichnet sich durch eine prächtige Fassade und einen imposanten Turm aus, der das Stadtbild des Erdbergs prägt."}]'::jsonb, ''),
  ('kunst-haus-wiin', 'Kunst Haus Wiin', '', '', '', '', 'Kunst Haus Wien', '[{"kategorie": "allg.", "text": "\"bedeutendes Museum und Ausstellungshaus im [[Weißgerberviertel]] im 3. Wiener Gemeindebezirk ([[Landstraße]])\""}, {"kategorie": "", "text": "Es widemt sich in erster Linie den Werken des österreichischen Künstlers Friedensreich Hundertwasser und ist zugleich ein herausragendes Beispiel für Hundertwassers einzigartigen architektonischen Stil, der sich durch organische Formen, unregelmäßige Strukturen und eine bunte, farbenfrohe Gestaltung auszeichnet. Das Kunst Haus Wien ist eine wichtige kulturelle Institution der Stadt"}, {"kategorie": "", "text": "Das Kunst Haus Wien wurde 1991 eröffnet und befindet sich in einem ehemaligen Thonet-Möbelfabrikgebäude, das nach Hundertwassers Entwürfen umgebaut und neu gestaltet wurde. Die Idee für das Kunst Haus Wien stammt direkt von Friedensreich Hundertwasser, der das Gebäude zu einem Kunstwerk machte und seine Philosophie von der Verschmelzung von Kunst und Natur in die Architektur einfließen ließ. Hundertwasser war sowohl für die Architektur als auch für die Innenausstattung des Museums verantwortlich, wodurch das Gebäude selbst zu einem Kunstobjekt wurde"}, {"kategorie": "", "text": "Die Fassade des Kunst Haus Wien ist bunt und unregelmäßig, mit farbigen Kacheln, begrünten Dächern und einer Vielzahl von Formen und Materialien, die die Wände und Fenster umrahmen. Typisch für Hundertwasser ist die Verwendung von natürlichen Formen und die Integration von Pflanzen in die Architektur"}, {"kategorie": "", "text": "Auch im Inneren setzt sich Hundertwassers Stil fort. Die Böden sind uneben, die Wände sind nicht rechtwinklig, und es gibt kaum gerade Linien. Das Ziel war, eine Umgebung zu schaffen, die den Betrachter in eine andere Welt versetzt, weit entfernt von der Norm der modernen Architektur"}, {"kategorie": "", "text": "Die Dauerausstellung zeigt das Leben und Werk von Friedensreich Hundertwasser, einschließlich seiner frühen Werke, seiner politischen und ökologischen Ansichten und seiner späteren architektonischen Projekte. Hier können Besucher tief in die Welt von Hundertwasser eintauchen und seine Vision von einer harmonischeren Welt nachvollziehen."}]'::jsonb, ''),
  ('prinz-eugen-schdrossn', 'Prinz-Eugen-Schdrossn', '', '', '', '', 'Prinz-Eugen-Straße', '[{"kategorie": "allg.", "text": "\"bedeutende Straße im 4. und 3. Wiener Gemeindebezirk ([[Wieden]] und [[Landstraße]])\""}, {"kategorie": "", "text": "Sie erstreckt sich vom [[Schwarzenbergplatz]] im Norden bis zur [[Wiedner]] Hauptstraße im Süden und führt dabei am [[Belvedere]], einem der bedeutendsten Barockschlösser Wiens, vorbei und bietet von der Anhöhe des Schlosses einen beeindruckenden Blick über die Stadt"}, {"kategorie": "", "text": "Die Straße wurde im späten 19. Jahrhundert angelegt und nach Prinz Eugen von Savoyen (1663–1736) benannt, einem der bedeutendsten Feldherren und Staatsmänner des Habsburgerreichs. Prinz Eugen ist besonders bekannt für seine Siege gegen die Osmanen und seine Rolle in den Türkenkriegen, weshalb ihm in Wien und ganz Österreich großer Respekt entgegengebracht wird"}, {"kategorie": "", "text": "Der nördliche Endpunkt der Prinz-Eugen-Straße ist der [[Schwarzenbergplatz]], ein großer öffentlicher Platz, der von imposanten Gebäuden umgeben ist und ein wichtiger Knotenpunkt in Wien darstellt"}]'::jsonb, ''),
  ('grof-schdahembeag-gossn', 'Grof Schdahembeag-Gossn', '', '', '', '', 'Graf Starhemberg-Gasse', '[{"kategorie": "allg.", "text": "Straße im 4. Wiener Gemeindebezirk ([[Wieden]])"}, {"kategorie": "", "text": "Sie verläuft in einem relativ kurzen Abschnitt zwischen der [[Favoritenstraße]] im Westen und der [[Wiedner]] Hauptstraße im Osten"}, {"kategorie": "", "text": "Die Straße ist nach der österreichischen Adelsfamilie Starhemberg und insbesondere nach Ernst Rüdiger von Starhemberg benannt, einem bedeutenden Feldherrn, der eine zentrale Rolle bei der Verteidigung Wiens während der Zweiten Türkenbelagerung im Jahr 1683 spielte"}, {"kategorie": "", "text": "Die Graf-Starhemberg-Gasse ist von typischen Wiener Wohn- und Geschäftshäusern aus dem 19. und frühen 20. Jahrhundert gesäumt. Viele der Gebäude in dieser Straße sind im Stil des [[Historismus]] und der [[Gründerzeit]] errichtet und tragen zur charakteristischen Architektur des Bezirks Wieden bei."}]'::jsonb, ''),
  ('palaeae-schdeanbeag', 'Palää Schdeanbeag', '', '', '', '', 'Palais Sternberg', '[{"kategorie": "allg.", "text": "\"historisches Gebäude im 3. Wiener Gemeindebezirk ([[Landstraße]]), das heute vor allem als Sitz der Italienischen Botschaft bekannt ist\""}, {"kategorie": "", "text": "Das Palais Sternberg liegt an der [[Ungargasse]] 43, in unmittelbarer Nähe zum [[Schloss]] Belvedere und zum [[Wiener]] Stadtpark"}, {"kategorie": "", "text": "Das Palais wurde in den 1820er Jahren für die Adelsfamilie Sternberg erbaut, eine der bedeutendsten Familien des österreichischen Adels. Die Familie Sternberg spielte eine wichtige Rolle in der Politik und Gesellschaft des Habsburgerreiches, und das Palais diente als einer ihrer Hauptwohnsitze in Wien"}, {"kategorie": "", "text": "Das Palais wurde im klassizistischen Stil errichtet, der durch seine klare Linienführung, harmonische Proportionen und zurückhaltende Dekoration gekennzeichnet ist. Das Gebäude ist ein typisches Beispiel für die Architektur dieser Epoche und spiegelt den Geschmack und die Vorlieben des österreichischen Adels im frühen 19. Jahrhundert wider."}]'::jsonb, ''),
  ('palaeae-mettanich', 'Palää Mettanich', '', '', '', '', 'Palais Metternich', '[{"kategorie": "allg.", "text": "\"prächtiges historisches Gebäude am [[Rennweg]] 27 im 3. Wiener Gemeindebezirk ([[Landstraße]])\""}, {"kategorie": "", "text": "Es wurde in der zweiten Hälfte des 19. Jahrhunderts erbaut und ist heute der Sitz der Deutschen Botschaft in Wien"}, {"kategorie": "", "text": "Das Palais ist ein herausragendes Beispiel für die Architektur des Historismus und ist eng mit der Geschichte des berühmten österreichischen Staatsmannes Fürst Klemens Wenzel von Metternich verbunden, nach dem es benannt wurde"}, {"kategorie": "", "text": "Das Palais wurde zwischen 1871 und 1874 für den österreichischen Politiker und Diplomaten Fürst Richard Klemens von Metternich-Winneburg, einen Nachkommen des berühmten Fürsten Klemens Wenzel von Metternich, im Stil des [[Historismus]] erbaut. Das Gebäude kombiniert Elemente der Neorenaissance mit barocken Stilelementen, was dem Palais eine imposante und repräsentative Erscheinung verleiht"}, {"kategorie": "", "text": "Mit seiner prächtigen Fassade und den luxuriösen Innenräumen spiegelt das Palais die politische und kulturelle Bedeutung der Familie Metternich sowie die enge Verbindung zwischen Deutschland und Österreich wider. Als Teil des Wiener [[Botschaftsviertels]] spielt das Palais eine zentrale Rolle im diplomatischen und kulturellen Leben der Stadt."}]'::jsonb, ''),
  ('nassau-palaeae', 'Nassau-Palää', '', '', '', '', 'Nassaupalais', '[{"kategorie": "allg.", "text": "\"historisches Gebäude im 3. Wiener Gemeindebezirk ([[Landstraße]]), heute als Sitz der Russischen Botschaft in Wien\""}, {"kategorie": "", "text": "Das Nassaupalais liegt in einem der zentralen und historisch bedeutenden Viertel Wiens, im sogenannten [[Botschaftsviertel]] des 3. Bezirks. Die [[Reisnerstraße]] ist für ihre zahlreichen diplomatischen Vertretungen bekannt, und das Nassaupalais ist eines der markantesten Gebäude in dieser Gegend"}, {"kategorie": "", "text": "Das Palais wurde im späten 19. Jahrhundert im Stil des [[Historismus]] erbaut und ist nach der Adelsfamilie Nassau benannt, die zu den bedeutenden aristokratischen Familien in Europa gehört. Das Gebäude spiegelt die architektonischen Vorlieben dieser Zeit wider und diente ursprünglich als repräsentatives Stadthaus"}, {"kategorie": "", "text": "Im 20. Jahrhundert wurde das Nassaupalais von der Sowjetunion und später von der Russischen Föderation übernommen und dient seither als Sitz der Russischen Botschaft in Wien. Das Palais ist ein zentraler Ort für die diplomatischen Beziehungen zwischen Russland und Österreich und spielt eine wichtige Rolle in den bilateralen Beziehungen."}]'::jsonb, ''),
  ('botanischa-goatn', 'Botanischa Goatn', '', '', '', '', 'Botanischer Garten', '[{"kategorie": "kurz für", "text": "\"Botanischer Garten der Universität Wien\" = bedeutende wissenschaftliche Einrichtung und ein öffentlicher Park im 3. Wiener Gemeindebezirk ([[Landstraße]])"}, {"kategorie": "", "text": "Der Botanische Garten wurde im Jahr 1754 von Kaiserin Maria Theresia gegründet und ist damit einer der ältesten botanischen Gärten in Europa. Er wurde ursprünglich als medizinischer Kräutergarten für die medizinische Fakultät der Universität Wien angelegt und diente der Ausbildung von Ärzten und Apothekern"}, {"kategorie": "", "text": "Der Garten wurde von Nikolaus Joseph von Jacquin, einem bedeutenden Botaniker und Arzt, geplant und aufgebaut. Er sammelte Pflanzen aus der ganzen Welt, was den Garten bald zu einem Zentrum der botanischen Forschung machte"}, {"kategorie": "", "text": "Im 19. Jahrhundert wurde der Garten unter der Leitung von Eduard Fenzl und Anton Kerner von Marilaun weiterentwickelt und modernisiert. Er wurde zunehmend auch für die Öffentlichkeit zugänglich gemacht und zu einem beliebten Ausflugsziel. In den folgenden Jahrzehnten wurden Gewächshäuser errichtet und die Sammlung um exotische Pflanzen erweitert"}, {"kategorie": "", "text": "Heute beherbergt der Botanische Garten der Universität Wienmehr als 11.000 Pflanzenarten aus verschiedenen Klimazonen und Regionen der Welt. Diese Vielfalt wird in unterschiedlichen thematischen Bereichen präsentiert, die sowohl wissenschaftlichen als auch pädagogischen Zwecken dienen (\"Alpinum\", \"Arboretum\" und diverse Gewächshäuser)"}, {"kategorie": "", "text": "Er grenzt an den [[Belvederegarten]], was ihm eine malerische Lage inmitten historisch und kulturell bedeutender Einrichtungen verleiht. Der Haupteingang befindet sich an der Mechelgasse, unweit der Straßenbahnlinien am [[Rennweg]]."}]'::jsonb, ''),
  ('wiina-arsenal', 'Wiina Arsenal', '', '', '', '', 'Wiener Arsenal', '[{"kategorie": "allg.", "text": "historischer Militärkomplex im 3. Wiener Gemeindebezirk ([[Landstraße]])"}, {"kategorie": "", "text": "Es wurde im 19. Jahrhundert als zentrale Waffen- und Munitionsfabrik sowie als Lager für die österreichisch-ungarische Armee errichtet"}, {"kategorie": "", "text": "Heute beherbergt das Arsenal unter anderem das [[Heeresgeschichtliche]] Museum, das bedeutendste Militärmuseum Österreichs, sowie verschiedene andere Einrichtungen"}, {"kategorie": "", "text": "Das Wiener Arsenal wurde zwischen 1848 und 1856 erbaut, in einer Zeit, in der die [[Habsburgermonarchie]] ihre militärische Infrastruktur modernisierte. Der Bau des Arsenals war eine direkte Reaktion auf die Revolutionen von 1848, als Wien ein Zentrum revolutionärer Bewegungen war und die Verteidigungsfähigkeit der Stadt gestärkt werden sollte"}, {"kategorie": "", "text": "[[Kaiser]] Franz Joseph I. ordnete den Bau des Arsenals an, um die österreichische Armee besser auszurüsten und die Verteidigung Wiens zu verbessern. Der Bau wurde von den Architekten Ludwig Förster und Theophil Hansen geleitet, die das Arsenal im Stil des [[Historismus]] entwarfen, inspiriert von mittelalterlichen Befestigungsanlagen"}, {"kategorie": "", "text": "Das Arsenal diente zunächst als Produktionsstätte und Lager für Waffen, Munition und militärische Ausrüstung. Es spielte eine zentrale Rolle in der militärischen Organisation der Habsburgermonarchie und blieb auch nach dem Ersten Weltkrieg ein wichtiger Standort für die österreichische Armee"}, {"kategorie": "", "text": "Heute hat das Wiener Arsenal seine ursprüngliche militärische Funktion weitgehend verloren. Einige der ehemaligen militärischen Gebäude wurden umgebaut und dienen nun als Büros oder Wohnungen. Der Komplex beherbergt auch Veranstaltungsräume und Bildungseinrichtungen, was das Arsenal zu einem lebendigen Teil des modernen Wiens macht."}]'::jsonb, ''),
  ('suedtirola-plotz', 'Südtirola Plotz', '', '', '', '', 'Südtiroler Platz', '[{"kategorie": "allg.", "text": "\"bedeutender Verkehrsknotenpunkt und öffentlicher Platz im 10. Wiener Gemeindebezirk ([[Favoriten]]), unmittelbar an der Grenze zum 4. Bezirk ([[Wieden]])\""}, {"kategorie": "", "text": "Der Platz liegt in der Nähe des [[Wiener]] Hauptbahnhofs, der größten und wichtigsten Eisenbahnstation der Stadt, und hat sowohl historische als auch verkehrstechnische Bedeutung für Wien"}, {"kategorie": "", "text": "Der Platz erhielt seinen Namen im Jahr 1927, als er nach der Region Südtirol benannt wurde, die nach dem Ersten Weltkrieg von Österreich an Italien abgetreten wurde. Der Name drückt die Verbundenheit Wiens mit dieser Region aus"}, {"kategorie": "", "text": "Der Südtiroler Platz entstand im Zuge der Stadterweiterung und der zunehmenden Bedeutung des Eisenbahnverkehrs in Wien. Er war zunächst ein wichtiger Knotenpunkt für Pferdebahnen und später für Straßenbahnen, bevor er zu einem zentralen Platz im öffentlichen Verkehrssystem Wiens wurde"}, {"kategorie": "", "text": "Mit dem Bau des neuen [[Wiener]] Hauptbahnhofs, der 2014 eröffnet wurde, und der Neugestaltung des Platzes hat sich der Südtiroler Platz zu einem der wichtigsten Verkehrsknotenpunkte Wiens entwickelt. Der Platz dient als zentraler Zugangspunkt zum Hauptbahnhof und ist ein Drehkreuz für den öffentlichen Nahverkehr, einschließlich [[U-Bahn]], [[Straßenbahn]] und Buslinien."}]'::jsonb, ''),
  ('wiina-u-baun', 'Wiina U-Baun', '', '', '', '', 'Wiener U-Bahn', '[{"kategorie": "allg.", "text": "\"zentrales U-Bahn-System der Stadt Wien, bestehend aus fünf Linien, die ein dichtes Netz von Stationen bedienen\""}, {"kategorie": "", "text": "Erste Überlegungen zu einem U-Bahn-System in Wien gehen bis ins späte 19. Jahrhundert zurück. Die heutige U-Bahn ging aus der ehemaligen [[Wiener]] Stadtbahn hervor, einem Nahverkehrssystem, das ab 1898 in Betrieb war und zunächst von Dampflokomotiven befahren wurde. In den 1920er Jahren wurde die Stadtbahn elektrifiziert, doch ein echtes U-Bahn-System wurde erst später realisiert"}, {"kategorie": "", "text": "Der Bau des modernen U-Bahn-Systems begann im Jahr 1969, als Wien begann, seine Verkehrsinfrastruktur den Anforderungen einer modernen Großstadt anzupassen. Die erste Strecke, die U1, wurde 1978 eröffnet. Seitdem wurde das Netz kontinuierlich ausgebaut"}, {"kategorie": "", "text": "Das Wiener U-Bahn-Netz wird von den Wiener Linien, dem städtischen Verkehrsunternehmen, betrieben und besteht derzeit aus fünf Linien, die durch unterschiedliche Farben und Nummern gekennzeichnet sind: (i) U1 (Rot): Diese Linie verläuft von Norden nach Süden und verbindet den Stadtteil [[Leopoldau]] im Norden mit [[Oberlaa]] im Süden. Sie durchquert dabei das Stadtzentrum und wichtige Knotenpunkte wie den [[Stephansplatz]] und den [[Wiener]] Hauptbahnhof;  (ii) U2 (Lila): Die U2 verbindet den Stadtteil [[Seestadt]] im Osten mit dem [[Karlsplatz]] im Stadtzentrum und soll in Zukunft bis Matzleinsdorfer Platz im Süden verlängert werden. Sie verläuft unter anderem durch das Pratergebiet und das Stadion;  (iii) U3 (Orange): Diese Linie verläuft in Ost-West-Richtung und verbindet [[Simmering]] im Südosten mit [[Ottakring]] im Westen. Die U3 durchquert das Zentrum Wiens und hält unter anderem an der Station [[Volkstheater]] und der Einkaufsstraße [[Mariahilfer]] Straße;  (iv) U4 (Grün): Die U4 folgt in Teilen der Trasse der ehemaligen [[Wiener]] Stadtbahn und verbindet [[Hütteldorf]] im Westen mit [[Heiligenstadt]] im Norden. Sie führt entlang des [[Donaukanals]] und durch den [[Stadtpark]];  (v) U6 (Braun): Die U6 verläuft in einem Bogen von Norden nach Süden, verbindet [[Floridsdorf]] im Norden mit [[Siebenhirten]] im Süden und folgt ebenfalls zum Teil den Trassen der alten [[Stadtbahn]]. Sie hat die meisten Stationen aller U-Bahn-Linien und deckt viele Bezirke Wiens ab."}]'::jsonb, ''),
  ('u-baun', 'U-Baun', '', '', '', '', 'U-Bahn', '[{"kategorie": "allg.", "text": "\"zentrales U-Bahn-System der Stadt Wien, bestehend aus fünf Linien, die ein dichtes Netz von Stationen bedienen\""}, {"kategorie": "", "text": "Erste Überlegungen zu einem U-Bahn-System in Wien gehen bis ins späte 19. Jahrhundert zurück. Die heutige U-Bahn ging aus der ehemaligen [[Wiener]] Stadtbahn hervor, einem Nahverkehrssystem, das ab 1898 in Betrieb war und zunächst von Dampflokomotiven befahren wurde. In den 1920er Jahren wurde die Stadtbahn elektrifiziert, doch ein echtes U-Bahn-System wurde erst später realisiert"}, {"kategorie": "", "text": "Der Bau des modernen U-Bahn-Systems begann im Jahr 1969, als Wien begann, seine Verkehrsinfrastruktur den Anforderungen einer modernen Großstadt anzupassen. Die erste Strecke, die U1, wurde 1978 eröffnet. Seitdem wurde das Netz kontinuierlich ausgebaut"}, {"kategorie": "", "text": "Das Wiener U-Bahn-Netz besteht derzeit aus fünf Linien, die durch unterschiedliche Farben und Nummern gekennzeichnet sind: (i) U1 (Rot): Diese Linie verläuft von Norden nach Süden und verbindet den Stadtteil [[Leopoldau]] im Norden mit [[Oberlaa]] im Süden. Sie durchquert dabei das Stadtzentrum und wichtige Knotenpunkte wie den [[Stephansplatz]] und den [[Wiener]] Hauptbahnhof;  (ii) U2 (Lila): Die U2 verbindet den Stadtteil [[Seestadt]] im Osten mit dem [[Karlsplatz]] im Stadtzentrum und soll in Zukunft bis Matzleinsdorfer Platz im Süden verlängert werden. Sie verläuft unter anderem durch das Pratergebiet und das Stadion;  (iii) U3 (Orange): Diese Linie verläuft in Ost-West-Richtung und verbindet [[Simmering]] im Südosten mit [[Ottakring]] im Westen. Die U3 durchquert das Zentrum Wiens und hält unter anderem an der Station [[Volkstheater]] und der Einkaufsstraße [[Mariahilfer]] Straße;  (iv) U4 (Grün): Die U4 folgt in Teilen der Trasse der ehemaligen [[Wiener]] Stadtbahn und verbindet [[Hütteldorf]] im Westen mit [[Heiligenstadt]] im Norden. Sie führt entlang des [[Donaukanals]] und durch den [[Stadtpark]];  (v) U6 (Braun): Die U6 verläuft in einem Bogen von Norden nach Süden, verbindet [[Floridsdorf]] im Norden mit [[Siebenhirten]] im Süden und folgt ebenfalls zum Teil den Trassen der alten [[Stadtbahn]]. Sie hat die meisten Stationen aller U-Bahn-Linien und deckt viele Bezirke Wiens ab."}]'::jsonb, ''),
  ('wiina-schdodtbaun', 'Wiina Schdodtbaun', '', '', '', '', 'Wiener Stadtbahn', '[{"kategorie": "allg.", "text": "\"ehemaliges Nahverkehrssystem in Wien, das Ende des 19. Jahrhunderts entwickelt wurde und die Grundlage für das heutige Wiener U-Bahn- und S-Bahn-System bildet\""}, {"kategorie": "", "text": "Die Wiener Stadtbahn wurde zwischen 1898 und 1901 eröffnet und war ein bedeutendes Infrastrukturprojekt der [[Habsburgermonarchie]]. Sie umfasste mehrere Linien, die die Stadt mit ihren Vororten verbanden und sowohl für den Personen- als auch für den Güterverkehr genutzt wurden"}, {"kategorie": "", "text": "Das Netz der Wiener Stadtbahn bestand aus vier Hauptstrecken, die radial um das Zentrum Wiens verliefen und die Stadtteile mit dem Stadtzentrum verbanden. Die wichtigsten Strecken waren:  (i) Wienflusslinie (heute Teil der U4): Diese Linie folgte dem Verlauf des [[Wienflusses]] und verband die westlichen Stadtteile, darunter [[Hütteldorf]], mit dem Stadtzentrum und endete in [[Heiligenstadt]];  (ii) Gürtellinie (heute Teil der U6): Diese Linie verlief entlang des [[Gürtels]], einer Ringstraße um das Zentrum Wiens, und verband die nördlichen und südlichen Bezirke miteinander;  (iii) Donaukanallinie: Diese Linie verlief entlang des [[Donaukanals]] und verband die östlichen Stadtteile mit dem zentralen Bereich Wiens;  (iv) [[Vorortelinie]] (heute Teil der S45): Diese Linie verband die Vororte Wiens und verlief in einem Bogen von Nordwesten nach Südosten durch die Außenbezirke"}, {"kategorie": "", "text": "Die Planung und der Bau der Stadtbahn wurden von bedeutenden Persönlichkeiten wie dem Architekten Otto Wagner, dem Ingenieur Wilhelm von Engerth und dem Stadtplaner und Politiker Karl Ritter von Ghega vorangetrieben"}, {"kategorie": "", "text": "Die Stadtbahn wurde zwischen 1898 und 1901 eröffnet und war von Anfang an sowohl für den Personen- als auch für den Güterverkehr ausgelegt. Sie wurde zunächst von Dampflokomotiven befahren, was sie von den später elektrifizierten Systemen unterschied"}, {"kategorie": "", "text": "Die Bahnhöfe der Stadtbahn, darunter berühmte Stationen wie [[Karlsplatz]], [[Gumpendorfer]] Straße und [[Schönbrunn]], zeichnen sich durch ihre elegante Gestaltung und die Verwendung moderner Materialien wie Glas und Eisen aus. Viele dieser Gebäude sind bis heute erhalten und stehen unter Denkmalschutz"}, {"kategorie": "", "text": "Die Stadtbahn umfasst auch zahlreiche Viadukte und Brücken, die über Straßen und Flüsse führten. Diese Bauwerke sind nicht nur funktional, sondern auch architektonisch beeindruckend und tragen zur charakteristischen Stadtsilhouette Wiens bei"}]'::jsonb, ''),
  ('haas-haus', 'Haas-Haus', '', '', '', '', 'Haas-Haus', '[{"kategorie": "allg.", "text": "markantes postmodernes Gebäude im 1. Wiener Gemeindebezirk ([[Innere]] Stadt), das direkt gegenüber dem [[Stephansdom]] am [[Stephansplatz]] steht"}, {"kategorie": "", "text": "Das 1990 eröffnete Gebäude wurde vom österreichischen Architekten Hans Hollein entworfen und gilt als eines der bekanntesten Beispiele moderner Architektur in Wien. Das Haas-Haus verbindet auf einzigartige Weise historische und moderne Elemente und hat sich seit seiner Eröffnung zu einem wichtigen Wahrzeichen der Stadt entwickelt"}, {"kategorie": "", "text": "Das Haas-Haus steht an der Stelle eines älteren Gebäudes, das ursprünglich im 19. Jahrhundert errichtet wurde. Das alte Haas-Haus war ein eher unscheinbarer Bau, der 1945 im Zweiten Weltkrieg schwer beschädigt wurde. In den 1980er Jahren beschloss man, das alte Gebäude abzureißen und an seiner Stelle ein neues, modernes Gebäude zu errichten"}, {"kategorie": "", "text": "Der Entwurf für das neue Haas-Haus stammt von Hans Hollein, einem der bedeutendsten Vertreter der Postmoderne in der Architektur. Hollein gewann den Wettbewerb mit einem Entwurf, der moderne Architektur mit der historischen Umgebung harmonisch zu verbinden versuchte"}, {"kategorie": "", "text": "Der Bau des Haas-Hauses war von Beginn an umstritten. Kritiker befürchteten, dass das moderne Design des Gebäudes nicht zur historischen Umgebung des Stephansplatzes passen würde und den Blick auf den Stephansdom beeinträchtigen könnte. Trotz dieser Bedenken wurde das Gebäude 1990 fertiggestellt und ist seither ein prägender Teil des Platzes"}, {"kategorie": "", "text": "Die Fassade des Haas-Hauses besteht aus einer Kombination von Glas, Stahl und Stein. Besonders auffällig ist die geschwungene Glasfront, die einen direkten Blick auf den Stephansdom ermöglicht und gleichzeitig die Umgebung reflektiert. Diese Gestaltung erzeugt ein spannungsvolles Spiel zwischen Transparenz und Spiegelung, das die Architektur des Doms in das moderne Gebäude einbindet"}, {"kategorie": "", "text": "Der Bau umfasst mehrere Stockwerke, die teils als Geschäftsräume, teils als Gastronomieflächen genutzt werden. Im obersten Stockwerk befindet sich ein Restaurant mit einem beeindruckenden Blick auf den Stephansdom."}]'::jsonb, ''),
  ('wiina-sschdrossnbaun', 'Wiina Sschdrossnbaun', '', '', '', '', 'Wiener Straßenbahn', '[{"kategorie": "allg.", "text": "\"eines der ältesten und umfangreichsten Straßenbahnsysteme der Welt und ein zentraler Bestandteil des öffentlichen Nahverkehrs in Wien, umgangssprachlich auch [[Bim]] genannt\""}, {"kategorie": "", "text": "Sie wird von den [[Wiener]] Linien betrieben und verbindet fast alle Bezirke der Stadt miteinander"}, {"kategorie": "", "text": "Das Wiener Straßenbahnnetz ist eines der größten in Europa und umfasst über 170 Kilometer Streckenlänge mit mehr als 30 Linien. Es erstreckt sich über fast das gesamte Stadtgebiet und verbindet die meisten Bezirke Wiens miteinander"}, {"kategorie": "", "text": "Eine der bekanntesten Strecken ist die Ringstraße, die um die Innere Stadt führt und wichtige Sehenswürdigkeiten wie die Staatsoper, das Rathaus und das Parlament passiert. Die Straßenbahnen auf dieser Strecke bieten nicht nur eine praktische Verbindung, sondern auch eine eindrucksvolle Stadtrundfahrt."}]'::jsonb, ''),
  ('heeresgeschichtliches-museum', 'Heeresgeschichtliches Museum', '', '', '', '', 'Heeresgeschichtliches Museum', '[{"kategorie": "allg.", "text": "\"ältestes und bedeutendstes Militärmuseum Österreichs\""}, {"kategorie": "", "text": "Es befindet sich im historischen [[Wiener]] Arsenal im 3. Wiener Gemeindebezirk ([[Landstraße]]) und widmet sich der Darstellung der österreichischen Militärgeschichte vom späten Mittelalter bis in die Gegenwart. Das Museum beherbergt eine beeindruckende Sammlung von Exponaten, die die militärische Geschichte und Entwicklung Österreichs über mehrere Jahrhunderte hinweg dokumentieren"}, {"kategorie": "", "text": "Das Heeresgeschichtliche Museum wurde in der Mitte des 19. Jahrhunderts auf Initiative von Kaiser Franz Joseph I. errichtet, um die militärischen Errungenschaften und die Geschichte der [[Habsburgermonarchie]] zu dokumentieren"}, {"kategorie": "", "text": "Der Bau des Museums begann 1850 als Teil des Wiener Arsenals und wurde 1856 abgeschlossen. Es war von Anfang an als zentrale Sammlung und Ausstellungsstätte für die militärische Geschichte des österreichischen Kaiserreichs konzipiert. Die offizielle Eröffnung fand 1891 statt, wobei das Museum damals noch als \"Kaiserlich-Königliches Hofwaffenmuseum\" bekannt war"}, {"kategorie": "", "text": "Das Gebäude des Heeresgeschichtlichen Museums ist ein herausragendes Beispiel für den [[Historismus]], entworfen von dem Architekten Ludwig Förster. Es zeigt Elemente der Neorenaissance und Neugotik und ist reich verziert, insbesondere im Eingangsbereich, der von Statuen und Reliefs berühmter österreichischer Militärführer geprägt ist. Der Innenraum ist ebenso imposant, mit großen Ausstellungshallen und prächtigen Sälen"}, {"kategorie": "", "text": "Das Heeresgeschichtliche Museum beherbergt eine der bedeutendsten Sammlungen zur Militärgeschichte in Europa. Die Exponate decken verschiedene Epochen ab, von den Türkenkriegen im 16. und 17. Jahrhundert, über die napoleonischen Kriege bis zu den beiden Weltkriegen und den jüngsten militärischen Einsätzen Österreichs"}, {"kategorie": "", "text": "Besonderes Highlight ist das Automobil, in dem [[Erzherzog]] Franz Ferdinand und seine Frau Sophie am 28. Juni 1914 in Sarajevo ermordet wurden, was den Ersten Weltkrieg auslöste."}]'::jsonb, 'Eazheazog Fraunz Ferdinand'),
  ('fluaridsduafa-bruckn', 'Fluaridsduafa Bruckn', '', '', '', '', 'Floridsdorfer Brücke', '[{"kategorie": "allg.", "text": "\"bedeutende Donaubrücke in Wien, die die Bezirke [[Floridsdorf]] (21. Bezirk) im Norden und [[Brigittenau]] (20. Bezirk) im Süden miteinander verbindet. Sie ist ein wichtiger Bestandteil des Wiener Verkehrsnetzes und dient sowohl dem Individualverkehr als auch dem öffentlichen Nahverkehr\""}, {"kategorie": "", "text": "Die ursprüngliche Brücke an dieser Stelle wurde 1874 errichtet und war damals eine wichtige Verbindung für den Verkehr zwischen Floridsdorf, das damals noch eine eigenständige Stadt war, und Wien. Sie war eine Eisenbahnbrücke, die auch für Fußgänger und Kutschenverkehr genutzt wurde"}, {"kategorie": "", "text": "Die Brücke wurde im Zweiten Weltkrieg zerstört und in den 1940er Jahren provisorisch wiederaufgebaut. Die heutige Floridsdorfer Brücke wurde schließlich in den 1970er Jahren neu errichtet und den modernen Verkehrsanforderungen angepasst."}]'::jsonb, ''),
  ('a22', 'A22', '', '', '', '', 'A22', '[{"kategorie": "allg.", "text": "\"wichtige Autobahn in Wien und Niederösterreich, die entlang des linken Ufers der [[Donau]] verläuft. Offiziell trägt sie die Bezeichnung [[Donauuferautobahn]], ist eine zentrale Verkehrsachse im Wiener Straßennetz und dient als Verbindung zwischen dem Stadtzentrum Wiens und den nördlichen und nordwestlichen Bezirken sowie weiter bis nach Niederösterreich\""}, {"kategorie": "", "text": "Die A22 wurde in den 1970er Jahren gebaut, um den Verkehr von und nach Wien effizienter zu gestalten und die Stadt an das überregionale Autobahnnetz anzubinden"}, {"kategorie": "", "text": "Die Donauuferautobahn (A22) verläuft durch landschaftlich reizvolle Gebiete entlang der Donau und bietet teilweise schöne Ausblicke auf den Fluss und die umliegenden Landschaften. Der Abschnitt durch Wien führt durch städtische Gebiete, während die weiter nördlichen Abschnitte durch ländliche Regionen und Weinbaugebiete führen."}]'::jsonb, ''),
  ('wiina-aussnring-schnoeoeschdrossn', 'Wiina Aussnring-Schnööschdrossn', '', '', '', '', 'Wiener Außenring-Schnellstraße', '[{"kategorie": "allg.", "text": "\"wichtige Schnellstraße im Großraum Wien (offiziell als S1 bezeichnet)\""}, {"kategorie": "", "text": "Sie ist Teil des Regionenrings um Wien und soll im Endausbau in einem östlichen Halbkreis um die Bundeshauptstadt herumführen und Stadtautobahnen wie die [[Donauuferautobahn]] A22, die [[Wiener]] Südosttangente A23 und die [[Wiener]] Nordrand-Schnellstraße S2 entlasten. Die S1 ist im Süden Teil der Europastraße E60 und im Norden Teil der E461. Ihre Länge beträgt mit Zubringer rund 63 Kilometer"}, {"kategorie": "", "text": "Derzeit sind die Süd- und die Nordumfahrung in Betrieb, die zwischen 2006 und 2010 eröffnet wurden."}]'::jsonb, ''),
  ('wiina-noadraund-schnoeoeschdrossn', 'Wiina Noadraund-Schnööschdrossn', '', '', '', '', 'Wiener Nordrand-Schnellstraße', '[{"kategorie": "allg.", "text": "\"Schnellstraße im Norden Wiens, die als wichtige Verkehrsverbindung innerhalb des Wiener Straßennetzes dient (offiziell als S2 bezeichnet)\""}, {"kategorie": "", "text": "Sie beginnt im Westen bei Knoten Hermann-Gebauer-Straße, wo sie an die A22 [[Donauufer]] Autobahn anschließt, und führt von dort aus in östlicher Richtung bis zum Knoten [[Süßenbrunn]], wo sie in die S1 [[Wiener]] Außenring-Schnellstraße übergeht. Die S2 verläuft hauptsächlich durch den 21. Bezirk ([[Floridsdorf]]) und den 22. Bezirk ([[Donaustadt]]):  3. Die S2 wurde in den 1990er Jahren geplant, um eine schnelle und direkte Verkehrsverbindung im Norden Wiens zu schaffen. Der Bau wurde in mehreren Abschnitten durchgeführt, um die Schnellstraße schrittweise in das bestehende Verkehrsnetz zu integrieren"}, {"kategorie": "", "text": "Der erste Abschnitt der S2 ging im Jahr 1993 in Betrieb. Weitere Abschnitte wurden in den folgenden Jahren fertiggestellt und eröffnet, wodurch die S2 zu einer wichtigen Verkehrsachse im Norden Wiens wurde."}]'::jsonb, ''),
  ('uno-city', 'UNO-City', '', '', '', '', 'UNO-City', '[{"kategorie": "allg.", "text": "\"bedeutender Komplex in Wien, der als einer der vier Hauptsitze der Vereinten Nationen (UN) weltweit dient (offiziell bekannt als Vienna International Centre [VIC])\""}, {"kategorie": "", "text": "Die UNO-City befindet sich im 22. Wiener Gemeindebezirk ([[Donaustadt]]), direkt an der [[Donau]], und ist ein wichtiger Standort für internationale Diplomatie und Zusammenarbeit"}, {"kategorie": "", "text": "Die UNO-City beherbergt verschiedene UN-Organisationen, die in Bereichen wie Friedenssicherung, Atomenergie, Drogenbekämpfung, Menschenrechte, industrielle Entwicklung und Migration tätig sind (IAEO, UNIDO, UNHCR, UNODC)"}, {"kategorie": "", "text": "Die Planungen für das Vienna International Centre begannen in den 1960er Jahren, als Wien sich als Standort für internationale Organisationen etablieren wollte. Der Grundstein für das Gebäude wurde 1973 gelegt, und der Komplex wurde am 23. August 1979 offiziell eröffnet"}, {"kategorie": "", "text": "Die UNO-City liegt im nördlichen Teil von Wien, direkt am Donauufer und gegenüber der [[Donauinsel]]. Der Komplex wurde vom österreichischen Architekten Johann Staber entworfen und besteht aus mehreren markanten Bürohochhäusern, die um einen zentralen Platz angeordnet sind. Die Gebäude sind durch ihre schlichte, moderne Architektur und ihre Funktionalität geprägt. Das VIC umfasst insgesamt etwa 230.000 Quadratmeter Bürofläche."}]'::jsonb, ''),
  ('brigittenaua-bruckn', 'Brigittenaua Bruckn', '', '', '', '', 'Brigittenauer Brücke', '[{"kategorie": "allg.", "text": "bedeutende Donaubrücke in Wien, die den 20. Bezirk ([[Brigittenau]]) mit dem 21. Bezirk ([[Floridsdorf]]) verbindet"}, {"kategorie": "", "text": "Sie überspannt die [[Donau]], den [[Donaukanal]] und die [[Donauinsel]] und verläuft von der Winarskystraße im 20. Bezirk über die Donau bis zur [[Donaufelder]] Straße im 21. Bezirk"}, {"kategorie": "", "text": "Die Brigittenauer Brücke wurde zwischen 1959 und 1962 erbaut und 1962 offiziell eröffnet. Der Bau der Brücke war Teil eines großangelegten Infrastrukturprojekts, das darauf abzielte, die Verkehrsführung in Wien zu modernisieren und zusätzliche Übergänge über die Donau zu schaffen"}, {"kategorie": "", "text": "Die Brigittenauer Brücke verfügt über separate Rad- und Fußwege, die es Radfahrern und Fußgängern ermöglichen, die Donau sicher zu überqueren. Diese Wege sind Teil des [[Wiener]] Radwegenetzes und bieten eine wichtige Verbindung zwischen den nördlichen und zentralen Bezirken."}]'::jsonb, ''),
  ('wiina-rodwegenetz', 'Wiina Rodwegenetz', '', '', '', '', 'Wiener Radwegenetz', '[{"kategorie": "allg.", "text": "\"umfangreiches und gut entwickeltes Netz von Radwegen, das sich über die gesamte Stadt Wien erstreckt\""}, {"kategorie": "", "text": "Das Wiener Radwegenetz erstreckt sich über alle 23 Bezirke Wiens und verbindet zentrale städtische Bereiche, Wohngebiete, Parks, Erholungsgebiete und wichtige Verkehrsknotenpunkte. Das Netz umfasst über 1.400 Kilometer Radwege (Stand: 2023) und ist in verschiedenen Bereichen der Stadt unterschiedlich ausgeprägt, je nach Verkehrsdichte und städtischer Umgebung"}, {"kategorie": "", "text": "In den Wiener Außenbezirken, besonders im [[Wienerwald]], gibt es spezielle Strecken für Mountainbiker, die sich durch hügeliges und bewaldetes Gelände schlängeln."}]'::jsonb, ''),
  ('kroftweak-freudenau', 'Kroftweak Freudenau', '', '', '', '', 'Kraftwerk Freudenau', '[{"kategorie": "allg.", "text": "\"Wasserkraftwerk an der Donau in Wien, das zur Erzeugung von elektrischer Energie dient\""}, {"kategorie": "", "text": "Es ist das jüngste und letzte Donaukraftwerk, das in Österreich errichtet wurde, und befindet sich im 2. Wiener Gemeindebezirk ([[Leopoldstadt]]), nahe der Grenze zum 11. Bezirk ([[Simmering]]). Das Kraftwerk spielt eine wichtige Rolle in der Energieversorgung der Stadt Wien und trägt zur nachhaltigen Stromerzeugung bei"}, {"kategorie": "", "text": "Die Planungen für das Kraftwerk Freudenau begannen in den 1980er Jahren. Der Bau des Kraftwerks selbst startete im Jahr 1992 und wurde 1998 abgeschlossen. Es war das letzte in einer Reihe von Donaukraftwerken, die entlang des österreichischen Donauabschnitts errichtet wurden. Das Projekt war technisch anspruchsvoll, da es den Schutz der umliegenden Naturgebiete und die Bedürfnisse des Schiffsverkehrs berücksichtigen musste"}, {"kategorie": "", "text": "Das Kraftwerk Freudenau ist ein sogenanntes Laufwasserkraftwerk, das die kontinuierliche Strömung der Donau nutzt, um Elektrizität zu erzeugen. Es hat eine installierte Leistung von etwa 172 Megawatt (MW) und produziert jährlich rund 1.100 Gigawattstunden (GWh) Strom, was etwa dem Strombedarf von 250.000 Haushalten entspricht"}, {"kategorie": "", "text": "Das Kraftwerk verfügt über sechs Kaplan-Turbinen, die besonders für Flüsse mit großen Wassermengen und geringen Gefällen geeignet sind. Die Turbinen sind in einem Maschinenhaus untergebracht, das auf der [[Donauinsel]] liegt. Der erzeugte Strom wird ins Wiener Netz eingespeist"}, {"kategorie": "", "text": "Neben der Stromerzeugung umfasst das Kraftwerk Freudenau auch eine große Schleusenanlage, die den Schiffsverkehr auf der Donau ermöglicht. Diese Schleuse ist eine der modernsten ihrer Art und kann auch große Schiffe und Schubverbände sicher passieren lassen."}]'::jsonb, ''),
  ('freidenaua-kroftweak', 'Freidenaua Kroftweak', '', '', '', '', 'Freudenauer Kraftwerk', '[{"kategorie": "allg.", "text": "\"Wasserkraftwerk an der Donau in Wien, das zur Erzeugung von elektrischer Energie dient\""}, {"kategorie": "", "text": "Es ist das jüngste und letzte Donaukraftwerk, das in Österreich errichtet wurde, und befindet sich im 2. Wiener Gemeindebezirk ([[Leopoldstadt]]), nahe der Grenze zum 11. Bezirk ([[Simmering]]). Das Kraftwerk spielt eine wichtige Rolle in der Energieversorgung der Stadt Wien und trägt zur nachhaltigen Stromerzeugung bei"}, {"kategorie": "", "text": "Die Planungen für das Kraftwerk Freudenau begannen in den 1980er Jahren. Der Bau des Kraftwerks selbst startete im Jahr 1992 und wurde 1998 abgeschlossen. Es war das letzte in einer Reihe von Donaukraftwerken, die entlang des österreichischen Donauabschnitts errichtet wurden. Das Projekt war technisch anspruchsvoll, da es den Schutz der umliegenden Naturgebiete und die Bedürfnisse des Schiffsverkehrs berücksichtigen musste"}, {"kategorie": "", "text": "Das Kraftwerk Freudenau ist ein sogenanntes Laufwasserkraftwerk, das die kontinuierliche Strömung der Donau nutzt, um Elektrizität zu erzeugen. Es hat eine installierte Leistung von etwa 172 Megawatt (MW) und produziert jährlich rund 1.100 Gigawattstunden (GWh) Strom, was etwa dem Strombedarf von 250.000 Haushalten entspricht"}, {"kategorie": "", "text": "Das Kraftwerk verfügt über sechs Kaplan-Turbinen, die besonders für Flüsse mit großen Wassermengen und geringen Gefällen geeignet sind. Die Turbinen sind in einem Maschinenhaus untergebracht, das auf der [[Donauinsel]] liegt. Der erzeugte Strom wird ins Wiener Netz eingespeist"}, {"kategorie": "", "text": "Neben der Stromerzeugung umfasst das Kraftwerk Freudenau auch eine große Schleusenanlage, die den Schiffsverkehr auf der Donau ermöglicht. Diese Schleuse ist eine der modernsten ihrer Art und kann auch große Schiffe und Schubverbände sicher passieren lassen."}]'::jsonb, ''),
  ('roobnhof-theata', 'Roobnhof Theata', '', '', '', '', 'Rabenhof Theater', '[{"kategorie": "allg.", "text": "\"Theater im 3. Wiener Gemeindebezirk ([[Landstraße]]), das sich in der [[Rabengasse]] 3 befindet\""}, {"kategorie": "", "text": "Es liegt inmitten der gleichnamigen Gemeindebauanlage [[Rabenhof]], die zwischen 1925 und 1928 erbaut wurde"}, {"kategorie": "", "text": "Ursprünglich war das Gebäude als Kinderhort sowie Gemeinschafts- und Veranstaltungsort für die Bewohner des [[Gemeindebaus]] geplant. Später wurde es in ein Kino umgebaut, das bis 1971 bestand"}, {"kategorie": "", "text": "Nach einer längeren Zeit der Nichtnutzung übernahm 1988 das [[Theater]] in der Josefstadt die Räumlichkeiten und baute sie zu einem Theatersaal mit 300 Plätzen um. Im Jahr 2000 wurde das Rabenhof Theater unter der Leitung des \"Vereins der Freunde und Förderer des Rabenhoftheaters\" eine eigenständige Bühne. Seit 2003, unter der Leitung von Thomas Gratzer, entwickelte sich das Theater zu einem fixen Bestandteil der österreichischen Theaterlandschaft"}, {"kategorie": "", "text": "Das Rabenhof Theater bietet ein vielfältiges Programm, das von Literaturabenden über Schauspiel, Kindertheater, Musical bis hin zu Politsatire reicht. Dabei wird ein starker Bezug zu österreichischen Themen und Lebenswelten hergestellt, wobei oft typische Wiener Figuren und Schauplätze im Fokus stehen."}]'::jsonb, ''),
  ('wiina-biidameiabautn', 'Wiina Biidameiabautn', '', '', '', '', 'Wiener Biedermeierbauten', '[{"kategorie": "allg.", "text": "\"Wohn- und Gebäudearchitektur, die während der [[Biedermeierzeit]] zwischen dem [[Wiener]] Kongress (1814/1815) und der Revolution von 1848 in Wien entstand\""}, {"kategorie": "", "text": "Diese Epoche ist geprägt von einer Rückbesinnung auf das Private und einer gezielten Abkehr vom politischen und öffentlichen Leben, als Reaktion auf den repressiven [[Metternichschen]] Polizeistaat mit seiner Zensur und dem Ausschluss des Bürgertums aus politischen Entscheidungen. Der Begriff „Biedermeier“ wurde zunächst für den Möbelstil verwendet, der durch schlichte, funktionale und elegante Formen gekennzeichnet war, später aber auch auf die bürgerliche Kultur und Architektur der Zeit übertragen"}, {"kategorie": "", "text": "Die Biedermeierarchitektur in Wien zeichnet sich durch ihre klare und unaufgeregte Gestaltung aus. Die Gebäude waren oft von schlichter Eleganz, mit einem Schwerpunkt auf Wohnkomfort und der Schaffung eines behaglichen, ästhetischen Lebensraums für das aufstrebende Bürgertum"}, {"kategorie": "", "text": "Bauten dieser Zeit neigen dazu, weniger monumental zu wirken als die Prachtbauten des [[Klassizismus]], sondern waren funktional und für die Bedürfnisse von Familien und Privatpersonen ausgelegt"}, {"kategorie": "", "text": "Typische Merkmale Wiener Biedermeierbauten: (i) schlichte, elegante Fassaden ohne übermäßige Verzierungen;  (ii) Verwendung von Naturmaterialien wie Holz und Stein, die zu einer harmonischen Wohnatmosphäre beitragen, (iii) einfache, aber funktionale Gestaltung der Innenräume, oft mit Möbeln im Biedermeierstil ausgestattet, (iv) Fokus auf helle, lichtdurchflutete Räume mit großen Fenstern, (v) Liebe zum Detail bei Fenstern, Türen und Verzierungen, die meist auf bürgerlichen Geschmack und Wohlstand hinwiesen, (vi) Integration von begrünten Innenhöfen und kleinen Gärten, die Rückzugsorte für das private Leben boten"}, {"kategorie": "", "text": "Biedermeierbauten spiegeln die Sehnsucht des Bürgertums nach einer Rückzugswelt wider, in der Kunst, Kultur und gesellschaftliches Leben in einem kleineren, intimen Rahmen stattfanden. In der Wohnarchitektur der Biedermeierzeit wird der Wohnraum zur „heilen Welt“ und zum Mittelpunkt des Lebens, weit entfernt von den politischen Wirren und der öffentlichen Sphäre"}, {"kategorie": "", "text": "Wien war während der [[Biedermeierzeit]] ein zentraler Ort dieser kulturellen Strömungen, und viele der Bauwerke, die aus dieser Zeit stammen, prägen noch heute das Stadtbild. Insbesondere in den damaligen Vororten Wiens, wie der [[Landstraße]] (3. Bezirk) oder [[Wieden]] (4. Bezirk), entstanden zahlreiche dieser charakteristischen Bauten, die sich durch ihre schlichte Schönheit und Funktionalität auszeichnen."}]'::jsonb, ''),
  ('koarlsbooda-beschluesse', 'Koarlsbooda Beschlüsse', '', '', '', '', 'Karlsbader Beschlüsse', '[{"kategorie": "allg.", "text": "\"eine Reihe von repressiven Maßnahmen, die im Jahr 1819 von den Vertretern der deutschen Staaten des [[Deutschen]] Bundes unter der Leitung von Fürst Klemens Wenzel Lothar von [[Metternich]] in Karlsbad (heute Karlovy Vary, Tschechien) verabschiedet wurden\""}, {"kategorie": "", "text": "Ihr Ziel war es, politische Unruhen zu unterdrücken und die aufkommenden liberalen und nationalen Bewegungen im Deutschen Bund zu bekämpfen"}, {"kategorie": "", "text": "Die Karlsbader Beschlüsse wurden als Reaktion auf die Ermordung des konservativen Schriftstellers August von Kotzebue durch den nationalistischen Studenten Karl Ludwig Sand getroffen. Metternich sah darin eine Bedrohung für die monarchische Ordnung in Europa und nutzte diesen Vorfall, um harte Maßnahmen gegen liberale und revolutionäre Bestrebungen durchzusetzen"}, {"kategorie": "", "text": "Die wichtigsten Punkte der Karlsbader Beschlüsse, die am 20. September 1819 verabschiedet wurden, waren: (i) Überwachung der Universitäten, (ii) Verbot der Burschenschaften, (iii) Zensur der Presse, sowie (iv) Errichtung einer Zentraluntersuchungskommission (diese Kommission in Mainz sollte „demagogische Umtriebe“ untersuchen, also jede Form von politischer Opposition. Sie koordinierte die Überwachung und Verfolgung von politischen Aktivisten im gesamten [[Deutschen]] Bund)"}, {"kategorie": "", "text": "Die Karlsbader Beschlüsse symbolisieren die restaurativen Bemühungen der Monarchen, die alten, vorrevolutionären Strukturen wiederherzustellen und den Aufstieg des Liberalismus und Nationalismus zu verhindern. Dies führte jedoch langfristig zu wachsendem Widerstand und Unzufriedenheit, die schließlich in die [[Revolution]] von 1848 mündeten."}]'::jsonb, ''),
  ('wiina-ministerialkonfarenz-von-1834', 'Wiina Ministerialkonfarenz von 1834', '', '', '', '', 'Wiener Ministerialkonferenz von 1834', '[{"kategorie": "allg.", "text": "\"Die Wiener Ministerialkonferenz von 1834 war ein Treffen der wichtigsten deutschen Staaten des [[Deutschen]] Bundes, das von Januar bis Juni 1834 auf Einladung Österreichs stattfand\""}, {"kategorie": "", "text": "Das Hauptziel der Konferenz war es, die politische Lage nach den revolutionären Bewegungen der frühen 1830er Jahre zu stabilisieren und Maßnahmen zu erörtern, um oppositionelle Bewegungen weiter zu unterdrücken. Die Konferenz wurde von den Großmächten Österreich und Preußen dominiert, wobei der österreichische Staatsmann Fürst Klemens von [[Metternich]] eine zentrale Rolle spielte"}, {"kategorie": "", "text": "Am Ende der Konferenz, am 12. Juni 1834, wurde ein Schlussprotokoll mit 60 Artikeln unterzeichnet. Dieses Protokoll bestand aus zwei Teilen: einem öffentlichen Teil, der als Bundesrecht offiziell verkündet wurde, und einem geheimen Teil, der nie offiziell veröffentlicht werden sollte"}, {"kategorie": "", "text": "Obwohl der geheime Teil der Konferenzbeschlüsse nie offiziell veröffentlicht werden sollte, gelang es der liberalen Opposition, die Dokumente durch den Hallgartenkreis (eine Gruppe liberaler Oppositioneller) an die Öffentlichkeit zu bringen. Diese Enthüllungen führten zu massiver Kritik an der autoritären Politik der Konferenzstaaten und schwächten deren Legitimität weiter"}, {"kategorie": "", "text": "Die Wiener Ministerialkonferenz von 1834 war ein Versuch, die restaurative Politik im [[Deutschen]] Bund zu festigen und jegliche liberalen oder nationalen Bewegungen zu unterdrücken. Allerdings wurde durch die Veröffentlichung der geheimen Bestimmungen die Glaubwürdigkeit der beteiligten Regierungen stark beschädigt, und die Umsetzungsmaßnahmen stießen vielerorts auf Widerstand. Die Geheimhaltung, die Pressezensur und die Verletzung von Landesrechten führten dazu, dass viele der geplanten Maßnahmen nicht durchgesetzt wurden"}, {"kategorie": "", "text": "Insgesamt trugen die repressiven Beschlüsse der Konferenz zur Verschärfung der politischen Spannungen bei und schürten den Unmut in der Bevölkerung, der schließlich in den [[Märzrevolutionen]] von 1848 seinen Höhepunkt fand."}]'::jsonb, ''),
  ('revolution-von-1848', 'Revolution von 1848', '', '', '', '', 'Revolution von 1848', '[{"kategorie": "allg.", "text": "\"Teil einer europaweiten bürgerlich-demokratischen Bewegung, die politische Reformen, Pressefreiheit und eine Verfassung forderte, jedoch nach blutigen Auseinandersetzungen von kaiserlichen Truppen niedergeschlagen wurde\""}, {"kategorie": "", "text": "Die Revolution in Wien war stark von der wirtschaftlichen Not und der sozialen Ungleichheit der Bevölkerung geprägt. Insbesondere der Hungerwinter 1847/1848 verschärfte die Lage"}, {"kategorie": "", "text": "Die Arbeiterklasse, die stark unter den schlechten Arbeitsbedingungen litt, war zunehmend verbittert, und die Forderungen nach politischen und sozialen Reformen wurden immer lauter. Die Aufhebung der Pressezensur und eine Verfassung standen dabei im Vordergrund"}, {"kategorie": "", "text": "Die Revolution begann in Wien am 13. März 1848. Die Bevölkerung stürmte das [[Ständehaus]], was zu den ersten gewalttätigen Auseinandersetzungen mit den staatlichen Kräften führte. Die Forderungen nach einer [[konstitutionellen]] Monarchie, Pressefreiheit und mehr politischen Rechten wurden laut. In der Nacht kam es zu Plünderungen und Brandstiftungen in den Vorstädten Wiens"}, {"kategorie": "", "text": "Der Staatskanzler Klemens Wenzel Lothar von [[Metternich]], Symbolfigur der reaktionären Politik und des Restaurationssystems, trat am 13. März 1848 zurück und floh nach England. Sein Rücktritt war ein großer Erfolg der Revolutionäre und ein Zeichen des Machtverlusts der alten Eliten"}, {"kategorie": "", "text": "Der Höhepunkt der Wiener Revolution war der [[Oktoberaufstand]]. Am 6. Oktober 1848 kam es zu einem letzten großen Aufstand in Wien, als die Bevölkerung versuchte, den Abmarsch kaiserlicher Truppen nach Ungarn zu verhindern, um die dortige Revolution zu unterstützen. Die Ermordung des Kriegsministers Graf Latour durch aufgebrachte Bürger war ein dramatischer Höhepunkt der Ereignisse"}, {"kategorie": "", "text": "Die Stadt Wien wurde in den folgenden Wochen von kaiserlichen Truppen unter der Führung von Feldmarschall Windischgrätz und dem kroatischen General Jelačić belagert und schließlich eingenommen"}, {"kategorie": "", "text": "Nach der blutigen Niederschlagung des Wiener Oktoberaufstands am 31. Oktober 1848 wurden viele Revolutionäre, darunter der Abgeordnete Robert Blum, hingerichtet. Mit dem Thronwechsel am 2. Dezember 1848, als [[Franz]] Joseph I. den Platz seines Onkels Ferdinand einnahm, begann eine Phase des [[Neoabsolutismus]]. Zwar waren viele Errungenschaften der Revolution – wie die Bauernbefreiung – unumkehrbar, doch politisch ging Österreich in die Repression zurück, und die Hoffnungen auf eine liberale Ordnung blieben unerfüllt."}]'::jsonb, ''),
  ('maerzrevolution-von-1848', 'Märzrevolution von 1848', '', '', '', '', 'Märzrevolution von 1848', '[{"kategorie": "allg.", "text": "\"Teil einer europaweiten bürgerlich-demokratischen Bewegung, die politische Reformen, Pressefreiheit und eine Verfassung forderte, jedoch nach blutigen Auseinandersetzungen von kaiserlichen Truppen niedergeschlagen wurde\""}, {"kategorie": "", "text": "Die Revolution in Wien war stark von der wirtschaftlichen Not und der sozialen Ungleichheit der Bevölkerung geprägt. Insbesondere der Hungerwinter 1847/1848 verschärfte die Lage"}, {"kategorie": "", "text": "Die Arbeiterklasse, die stark unter den schlechten Arbeitsbedingungen litt, war zunehmend verbittert, und die Forderungen nach politischen und sozialen Reformen wurden immer lauter. Die Aufhebung der Pressezensur und eine Verfassung standen dabei im Vordergrund"}, {"kategorie": "", "text": "Die Revolution begann in Wien am 13. März 1848. Die Bevölkerung stürmte das [[Ständehaus]], was zu den ersten gewalttätigen Auseinandersetzungen mit den staatlichen Kräften führte. Die Forderungen nach einer [[konstitutionellen]] Monarchie, Pressefreiheit und mehr politischen Rechten wurden laut. In der Nacht kam es zu Plünderungen und Brandstiftungen in den Vorstädten Wiens"}, {"kategorie": "", "text": "Der Staatskanzler Klemens Wenzel Lothar von [[Metternich]], Symbolfigur der reaktionären Politik und des Restaurationssystems, trat am 13. März 1848 zurück und floh nach England. Sein Rücktritt war ein großer Erfolg der Revolutionäre und ein Zeichen des Machtverlusts der alten Eliten"}, {"kategorie": "", "text": "Der Höhepunkt der Wiener Revolution war der [[Oktoberaufstand]]. Am 6. Oktober 1848 kam es zu einem letzten großen Aufstand in Wien, als die Bevölkerung versuchte, den Abmarsch kaiserlicher Truppen nach Ungarn zu verhindern, um die dortige Revolution zu unterstützen. Die Ermordung des Kriegsministers Graf Latour durch aufgebrachte Bürger war ein dramatischer Höhepunkt der Ereignisse"}, {"kategorie": "", "text": "Die Stadt Wien wurde in den folgenden Wochen von kaiserlichen Truppen unter der Führung von Feldmarschall Windischgrätz und dem kroatischen General Jelačić belagert und schließlich eingenommen"}, {"kategorie": "", "text": "Nach der blutigen Niederschlagung des Wiener Oktoberaufstands am 31. Oktober 1848 wurden viele Revolutionäre, darunter der Abgeordnete Robert Blum, hingerichtet. Mit dem Thronwechsel am 2. Dezember 1848, als [[Franz]] Joseph I. den Platz seines Onkels [[Ferdinand]] I. einnahm, begann eine Phase des [[Neoabsolutismus]]. Zwar waren viele Errungenschaften der Revolution – wie die Bauernbefreiung – unumkehrbar, doch politisch ging Österreich in die Repression zurück, und die Hoffnungen auf eine liberale Ordnung blieben unerfüllt."}]'::jsonb, ''),
  ('oktobaaufschdaund-von-1848', 'Oktobaaufschdaund von 1848', '', '', '', '', 'Oktoberaufstand von 1848', '[{"kategorie": "allg.", "text": "\"letzter Aufstand der österreichischen Revolution, bei dem revolutionäre Kräfte Wien besetzten, bis die Stadt von kaiserlichen Truppen unter Feldmarschall Windischgraetz und dem kroatischen General Jelačić blutig zurückerobert wurde (auch als \"Wiener Oktoberrevolution\" bezeichnet)\""}, {"kategorie": "", "text": "Nach heftigen Straßenkämpfen und der Eroberung Wiens durch die Aufständischen floh Kaiser [[Ferdinand]] I. mit seinem Hof nach Olmütz. Die kaiserliche Gegenoffensive, angeführt von Fürst Windisch-Graetz und Banus Joseph Jelačić, führte nach mehreren Tagen schwerer Kämpfe, darunter die Schlacht bei Schwechat, zur gewaltsamen Rückeroberung Wiens am 31. Oktober"}, {"kategorie": "", "text": "Der Aufstand endete mit blutigen Repressionen, darunter die Hinrichtung wichtiger Revolutionäre wie Robert Blum, und markierte das Ende der [[Märzrevolution]] sowie den Übergang Österreichs in eine Phase des [[Neoabsolutismus]] unter [[Kaiser]] Franz Joseph I."}]'::jsonb, ''),
  ('wiina-oktobaaufschdaund', 'Wiina Oktobaaufschdaund', '', '', '', '', 'Wiener Oktoberaufstand', '[{"kategorie": "allg.", "text": "\"letzter Aufstand der österreichischen Revolution im Oktober 1848, bei dem revolutionäre Kräfte Wien besetzten, bis die Stadt von kaiserlichen Truppen unter Feldmarschall Windischgraetz und dem kroatischen General Jelačić blutig zurückerobert wurde (auch als \"Wiener Oktoberrevolution\" bezeichnet)\""}, {"kategorie": "", "text": "Nach heftigen Straßenkämpfen und der Eroberung Wiens durch die Aufständischen floh Kaiser [[Ferdinand]] I. mit seinem Hof nach Olmütz. Die kaiserliche Gegenoffensive, angeführt von Fürst Windisch-Graetz und Banus Joseph Jelačić, führte nach mehreren Tagen schwerer Kämpfe, darunter die Schlacht bei Schwechat, zur gewaltsamen Rückeroberung Wiens am 31. Oktober"}, {"kategorie": "", "text": "Der Aufstand endete mit blutigen Repressionen, darunter die Hinrichtung wichtiger Revolutionäre wie Robert Blum, und markierte das Ende der [[Märzrevolution]] sowie den Übergang Österreichs in eine Phase des [[Neoabsolutismus]] unter [[Kaiser]] Franz Joseph I."}]'::jsonb, ''),
  ('metternichna-polizeischdood', 'Metternichna Polizeischdood', '', '', '', '', 'Metternichner Polizeistaat', '[{"kategorie": "allg.", "text": "\"autoritäres politisches System, das unter dem österreichischen Staatskanzler Fürst Klemens Wenzel von [[Metternich]] zwischen 1815 und 1848 im [[Kaisertum]] Österreich etabliert wurde\""}, {"kategorie": "", "text": "Diese Herrschaftsform war durch eine strenge Zensur, ein umfassendes Spitzelwesen und die weitreichende Überwachung der Bevölkerung gekennzeichnet. Ziel war es, jegliche Formen von liberalen, nationalistischen oder revolutionären Bewegungen im Keim zu ersticken und die monarchische Ordnung sowie das konservative Machtgefüge zu bewahren, das nach den [[napoleonischen]] Kriegen und dem [[Wiener]] Kongress wiederhergestellt worden war"}, {"kategorie": "", "text": "Unter Metternichs Regime wurden politische Freiheiten stark eingeschränkt. Publikationen, Versammlungen und Vereine unterlagen einer scharfen Kontrolle, und die Geheimpolizei durchdrang weite Teile der Gesellschaft, um potenzielle Regimegegner zu identifizieren und zu neutralisieren. Besonders betroffen waren Intellektuelle, Schriftsteller und politische Aktivisten, die durch die [[Karlsbader]] Beschlüsse von 1819 zusätzlich überwacht wurden"}, {"kategorie": "", "text": "Metternichs Ziel war es, die Herrschaft der [[Habsburger]] Monarchie im [[Vielvölkerstaat]] Österreich aufrechtzuerhalten und gleichzeitig die revolutionären Bewegungen, die in ganz Europa an Stärke gewannen, zu verhindern"}, {"kategorie": "", "text": "Die als [[Vormärz]] bekannte Ära, die in Österreich stark mit dem Metternichschen Polizeistaat verbunden ist, endete schließlich 1848 mit der [[Märzrevolution]], die zum Rücktritt Metternichs und zur zeitweiligen Abschaffung vieler repressiver Maßnahmen führte."}]'::jsonb, ''),
  ('wiina-schdaendehaus', 'Wiina Schdändehaus', '', '', '', '', 'Wiener Ständehaus', '[{"kategorie": "allg.", "text": "Versammlungsort der Landstände (=die Vertreter des Adels, des Klerus und der Bürger), die in einem Landtag über politische und wirtschaftliche Angelegenheiten entschieden"}, {"kategorie": "", "text": "Neben den Versammlungen diente das Gebäude in der [[Herrengasse]] auch als Sitz der ständischen Behörden"}, {"kategorie": "", "text": "In der Revolution von 1848 in Wien wurde das Ständehaus zu einem symbolträchtigen Ort. Am 13. März 1848 stürmten revolutionäre Kräfte das Gebäude, was den Beginn der bürgerlichen Aufstände in der Stadt markierte"}, {"kategorie": "", "text": "Diese Aktion folgte auf die Verlesung einer Rede des ungarischen Nationalisten Lajos Kossuth, die Reformen und eine konstitutionelle Umgestaltung des Kaiserreichs forderte"}, {"kategorie": "", "text": "Der Sturm auf das Ständehaus führte zu weiteren Unruhen und Plünderungen in den Wiener Vorstädten, bei denen das Bürgermilitär mit Gewalt gegen die Aufständischen vorging. Die Ereignisse dieses Tages forderten insgesamt 46 Todesopfer und läuteten eine Phase der politischen und sozialen Erhebung gegen das autoritäre System ein"}]'::jsonb, ''),
  ('dschoadsch-woaschingtn-hof', 'Dschoadsch-Woaschingtn-Hof', '', '', '', '', 'George-Washington-Hof', '[{"kategorie": "allg.", "text": "bedeutende Wohnanlage im 10. Wiener Gemeindebezirk ([[Favoriten]])"}, {"kategorie": "", "text": "Er wurde in den 1920er Jahren im Rahmen des großen kommunalen Wohnbauprogramms der Stadt Wien, bekannt als à„Rotes Wien“, errichtet, das darauf abzielte, erschwinglichen Wohnraum für die Arbeiterklasse zu schaffen"}, {"kategorie": "", "text": "Der George-Washington-Hof ist nach dem ersten Präsidenten der Vereinigten Staaten, George Washington, benannt und ist ein Beispiel für die internationale Ausrichtung und den kosmopolitischen Geist, den die Stadt Wien in dieser Zeit verkörperte"}, {"kategorie": "", "text": "Der George-Washington-Hof wurde zwischen 1927 und 1930 nach den Plänen der Architekten Karl Krist und Robert Oerley gebaut. Die Anlage umfasst etwa 1000 Wohnungen besteht aus mehreren großen, miteinander verbundenen Wohnblöcken, die sich um Innenhöfe gruppieren"}, {"kategorie": "", "text": "Der George-Washington-Hof spielte, wie viele andere Wiener Gemeindebauten, eine Rolle in den politischen Auseinandersetzungen der Zwischenkriegszeit. Während der [[Februarkämpfe]] von 1934 war die Wohnanlage, wie viele andere Gemeindebauten auch, ein Ort des Widerstands gegen die austrofaschistische Regierung. Die Kämpfe endeten jedoch mit der Niederlage der sozialistischen Arbeiterbewegung. Heute steht der George-Washington-Hof unter Denkmalschutz und ist weiterhin ein aktiver Wohnort für viele Wienerinnen und Wiener."}]'::jsonb, ''),
  ('koarl-marx-hof', 'Koarl-Marx-Hof', '', '', '', '', 'Karl-Marx-Hof', '[{"kategorie": "allg.", "text": "\"eine der bekanntesten und größten kommunalen Wohnanlagen in Wien, die als ein herausragendes Beispiel für den sozialen Wohnbau der Zwischenkriegszeit gilt\""}, {"kategorie": "", "text": "Er befindet sich im 19. Wiener Gemeindebezirk ([[Döbling]]) und wurde zwischen 1927 und 1930 im Rahmen des groß angelegten Wohnbauprogramms des à„Roten Wien“ errichtet. Der Karl-Marx-Hof ist nach dem deutschen Philosophen und Ökonomen Karl Marx benannt, was die sozialistische Ausrichtung der damaligen Wiener Stadtregierung unterstreicht"}, {"kategorie": "", "text": "Der Karl-Marx-Hof wurde von dem österreichischen Architekten Karl Ehn entworfen, der ein Schüler von Otto Wagner war, einem der bedeutendsten Vertreter der Wiener Moderne. Der Bau des Karl-Marx-Hofes begann im Jahr 1927 und wurde 1930 abgeschlossen. Mit einer Länge von über einem Kilometer gilt der Karl-Marx-Hof als eine der längsten zusammenhängenden Wohnanlagen der Welt. Die Anlage erstreckt sich über eine Fläche von etwa 156.000 Quadratmetern und umfasste ursprünglich rund 1.382 Wohnungen"}, {"kategorie": "hist.", "text": "Der Karl-Marx-Hof spielte eine zentrale Rolle in den politischen Auseinandersetzungen der 1930er Jahre. Während der [[Februarkämpfe]] von 1934, einem bewaffneten Konflikt zwischen der sozialistischen Arbeiterbewegung und der austrofaschistischen Regierung, war der Karl-Marx-Hof einer der Hauptschauplätze des Widerstands. Die Anlage wurde von den Sozialdemokraten als eine Art Festung verteidigt, bevor sie schließlich von den Regierungstruppen eingenommen wurde"}, {"kategorie": "", "text": "Nach dem Bürgerkrieg und der Machtergreifung der austrofaschistischen Regierung wurden viele sozialdemokratische Symbole, darunter auch der Name des Karl-Marx-Hofes, entfernt. Der ursprüngliche Name wurde jedoch nach dem Zweiten Weltkrieg wieder eingeführt, und die Anlage blieb ein starkes Symbol für den sozialen Wohnbau in Wien"}, {"kategorie": "", "text": "Heute steht der Karl-Marx-Hof unter Denkmalschutz und ist weiterhin ein bewohntes Wohnviertel. Er ist ein wichtiger Bestandteil des kulturellen Erbes Wiens und ein lebendiges Beispiel für die Vision des à„Roten Wien“ von sozialem Wohnbau. Der Karl-Marx-Hof beherbergt heute auch den „Waschsalon Karl-Marx-Hof“, ein Museum, das der Geschichte des Roten Wien und dem sozialen Wohnbau gewidmet ist."}]'::jsonb, ''),
  ('roodes-wiin', 'Roodes Wiin', '', '', '', '', 'Rotes Wien', '[{"kategorie": "allg.", "text": "\"Periode in der Geschichte Wiens, die von 1919 bis 1934 dauerte, während der die Stadt von der Sozialdemokratischen Arbeiterpartei (SDAP) regiert wurde\""}, {"kategorie": "", "text": "Diese Zeit ist besonders bemerkenswert für die umfangreichen sozialen und städtebaulichen Reformen, die die Stadt Wien grundlegend veränderten. Der Begriff \"Rot\" steht dabei symbolisch für den Sozialismus und die sozialdemokratische Politik, die in dieser Ära dominiert hat"}, {"kategorie": "", "text": "Das \"Rote Wien\" ist besonders bekannt für seine ambitionierte Sozial- und Wohnbaupolitik. In dieser Zeit wurden zahlreiche [[Gemeindebauten]] errichtet – soziale Wohnbauprojekte, die erschwinglichen Wohnraum für Arbeiter und sozial Schwache zur Verfügung stellten. Insgesamt wurden über 60.000 Wohnungen gebaut, darunter bekannte Wohnanlagen wie der [[Karl-Marx-Hof]], der [[George-Washington-Hof]], der [[Sandleitenhof]], der [[Goethehof]] und der [[Rabenhof]]"}, {"kategorie": "", "text": "Die Periode des \"Roten Wien\" endete abrupt 1934 mit dem österreichischen Bürgerkrieg und der darauffolgenden Errichtung des austrofaschistischen Ständestaates. Die Sozialdemokraten wurden entmachtet, viele ihrer Reformen wurden zurückgenommen, und die [[Gemeindebauten]], die während des Bürgerkriegs als Widerstandszentren dienten, wurden teilweise beschädigt oder umbenannt"}, {"kategorie": "", "text": "Das \"Rote Wien\" hinterließ ein bleibendes Vermächtnis, das bis heute in der Stadt spürbar ist. Die sozialen Wohnbauten aus dieser Zeit prägen noch immer das Stadtbild und sind ein wichtiger Bestandteil der Wiener Identität. Die Ideen und Konzepte des \"Roten Wien\" beeinflussten die Stadtplanung und Sozialpolitik weltweit und werden bis heute als Beispiel für erfolgreiche kommunale Sozialpolitik betrachtet."}]'::jsonb, ''),
  ('rossaua-laende', 'Rossaua Lände', '', '', '', '', 'Rossauer Lände', '[{"kategorie": "allg.", "text": "\"wichtige Straße und Uferpromenade im 9. Wiener Gemeindebezirk ([[Alsergrund]])\""}, {"kategorie": "", "text": "Sie verläuft entlang des rechten Ufers des [[Donaukanals]] und ist sowohl eine bedeutende Verkehrsverbindung als auch ein historisch und städtebaulich interessantes Gebiet in Wien"}, {"kategorie": "", "text": "Die Rossauer Lände erstreckt sich von der [[Friedensbrücke]] im Norden bis zur [[Franzensbrücke]] im Süden und bildet die Grenze zwischen dem [[Donaukanal]] und dem dicht bebauten Stadtgebiet des 9. Bezirks"}, {"kategorie": "hist.", "text": "Der Name \"Rossauer Lände\" leitet sich von der ehemaligen Vorstadt Rossau ab, die heute Teil des 9. Bezirks ist. Historisch war die Gegend von Rossau geprägt von Handwerkern, kleinen Gewerbebetrieben und später auch von Kasernen und militärischen Einrichtungen. Die Lände war ursprünglich ein wichtiger Anlegeplatz für Schiffe, die Waren entlang des Donaukanals transportierten. Der Donaukanal selbst war bis ins 19. Jahrhundert ein wichtiger Handelsweg, und die Rossauer Lände diente als Umschlagsplatz für Waren, die nach Wien gebracht wurden"}, {"kategorie": "", "text": "Heute ist die Rossauer Lände nicht nur eine wichtige Verkehrsverbindung, sondern auch ein beliebter Ort für Spaziergänge und Freizeitaktivitäten entlang des Donaukanals. Der Kanalbereich wurde in den letzten Jahren zunehmend zu einem Erholungsgebiet umgestaltet, mit Cafés, Bars und Freizeitmöglichkeiten, die insbesondere in den Sommermonaten viele Menschen anziehen."}]'::jsonb, ''),
  ('eadbeaga-laende', 'Eadbeaga Lände', '', '', '', '', 'Erdberger Lände', '[{"kategorie": "allg.", "text": "bedeutende Straße in Wien, die sich im 3. Wiener Gemeindebezirk ([[Landstraße]]) befindet"}, {"kategorie": "", "text": "Sie verläuft entlang des rechten Ufers des [[Donaukanals]] und erstreckt sich von der [[Schüttelstraße]] im Westen bis zum [[Praterkai]] im Osten"}, {"kategorie": "", "text": "Der Name \"Erdberger Lände\" leitet sich vom historischen Vorort [[Erdberg]] ab, der heute ein Teil des 3. Bezirks ist. „Lände“ bezeichnet traditionell einen Uferbereich, der für das Anlegen von Schiffen oder das Be- und Entladen von Gütern genutzt wird. In früheren Zeiten diente die Erdberger Lände als Anlegestelle am Donaukanal"}, {"kategorie": "", "text": "Die Erdberger Lände trägt zur urbanen Landschaft Wiens bei und verbindet traditionelle Wiener Architektur mit moderner Bebauung. Durch ihre Nähe zum Donaukanal bietet sie sowohl eine praktische Verkehrsverbindung als auch einen Zugang zum Freizeit- und Erholungsgebiet am Donaukanal."}]'::jsonb, ''),
  ('laxnbuaga-schdrossn', 'Laxnbuaga Schdrossn', '', '', '', '', 'Laxenburger Straße', '[{"kategorie": "allg.", "text": "\"bedeutende Verkehrsstraße im Süden von Wien, die durch den 10. Wiener Gemeindebezirk ([[Favoriten]]) verläuft\""}, {"kategorie": "", "text": "Sie beginnt im Bereich des [[Südtiroler]] Platzes in der Nähe des [[Hauptbahnhofs]] Wien und verläuft in südlicher Richtung aus der Stadt hinaus. Die Straße ist nach dem Ort Laxenburg benannt, der südlich von Wien liegt und bekannt für das Schloss Laxenburg ist, eine ehemalige Sommerresidenz der [[Habsburger]]"}, {"kategorie": "", "text": "Die Laxenburger Straße hat eine lange Geschichte und war ursprünglich Teil der Verbindung zwischen Wien und dem Schloss Laxenburg, das im 18. und 19. Jahrhundert eine wichtige Sommerresidenz der kaiserlichen Familie war. Die Straße diente daher nicht nur als Verkehrsweg, sondern auch als wichtige Verbindung für repräsentative Fahrten der Habsburger"}, {"kategorie": "", "text": "Im Laufe der Industrialisierung und des städtischen Wachstums wurde die Laxenburger Straße zu einer wichtigen Verkehrsachse für den Gütertransport und die Erschließung neuer Wohn- und Industriegebiete im Süden Wiens"}, {"kategorie": "", "text": "Heute ist die Laxenburger Straße eine bedeutende städtische Achse, die sowohl das historische Erbe Wiens als auch seine moderne Entwicklung widerspiegelt. Sie verbindet traditionelle Wohnviertel mit neuen städtebaulichen Projekten und Industriestandorten."}]'::jsonb, ''),
  ('triista-schdrossn', 'Triista Schdrossn', '', '', '', '', 'Triesterstraße', '[{"kategorie": "allg.", "text": "\"bedeutende Verkehrsstraße in Wien, die sich vom Stadtzentrum in Richtung Süden erstreckt und nach der italienischen Stadt Triest benannt ist, die historisch eine wichtige Hafenstadt der [[Habsburgermonarchie]] war\""}, {"kategorie": "", "text": "Die Triester Straße beginnt im Bereich des [[Matzleinsdorfer]] Platzes im 5. Wiener Gemeindebezirk ([[Margareten]]) und verläuft in südlicher Richtung durch den 10. Bezirk ([[Favoriten]])"}, {"kategorie": "", "text": "Die Triester Straße hat eine lange Geschichte als wichtige Verbindungsstraße zwischen Wien und den südlichen Gebieten der Habsburgermonarchie. Triest war als Hafenstadt von großer wirtschaftlicher Bedeutung für das Reich, und die Straße diente als zentrale Verbindung zu diesem wichtigen Handelsplatz"}, {"kategorie": "", "text": "Heute ist die Triester Straße nicht nur eine wichtige Verkehrsachse, sondern auch ein Standort für zahlreiche Gewerbebetriebe, Einkaufszentren und Dienstleister. In den letzten Jahren wurden entlang der Straße mehrere städtebauliche Projekte durchgeführt, um die Infrastruktur zu modernisieren und die Straße an die Bedürfnisse des zunehmenden Verkehrs anzupassen"}]'::jsonb, ''),
  ('adalbeat-schdifta-schdrossn', 'Adalbeat-Schdifta-Schdrossn', '', '', '', '', 'Adalbert-Stifter-Straße', '[{"kategorie": "allg.", "text": "\"Straße im 20. Wiener Gemeindebezirk ([[Brigittenau]]), die in Ost-West-Richtung verläuft und mehrere wichtige Straßen innerhalb des Bezirks verbindet\""}, {"kategorie": "", "text": "Die Adalbert-Stifter-Straße beginnt im Westen an der [[Jägerstraße]], einer der Hauptverkehrsstraßen Brigittenaus, und verläuft in östlicher Richtung"}, {"kategorie": "", "text": "Die Straße ist nach dem österreichischen Schriftsteller, Maler und Pädagogen Adalbert Stifter (1805–1868) benannt, der für seine Werke der Biedermeier-Literatur bekannt ist. Stifter war ein einflussreicher Schriftsteller des 19. Jahrhunderts, dessen Werke oft idyllische Landschaftsbeschreibungen und moralische Erzählungen enthalten"}, {"kategorie": "", "text": "Die Adalbert-Stifter-Straße ist von einer Mischung aus Wohnhäusern und einigen Geschäftsgebäuden gesäumt. Die Gebäude entlang der Straße stammen größtenteils aus dem späten 19. und frühen 20. Jahrhundert, was dem Gebiet ein historisches und urbanes Flair verleiht."}]'::jsonb, ''),
  ('klostaneibuaga-schdrossn', 'Klostaneibuaga Schdrossn', '', '', '', '', 'Klosterneuburger Straße', '[{"kategorie": "allg.", "text": "\"bedeutende Verkehrsstraße im 20. Wiener Gemeindebezirk ([[Brigittenau]]), die sich in Nord-Süd-Richtung erstreckt und das Wiener Stadtzentrum mit den nördlich gelegenen Stadtteilen und Vororten verbindet, darunter die Stadt Klosterneuburg, nach der sie benannt ist\""}, {"kategorie": "", "text": "Die Klosterneuburger Straße beginnt im Süden an der Grenze zum 9. Wiener Gemeindebezirk ([[Alsergrund]]), in der Nähe des [[Augartens]], und verläuft in nördlicher Richtung durch Brigittenau. Sie endet im Norden des Bezirks und setzt sich außerhalb der Stadtgrenzen von Wien als Bundesstraße fort, die nach Klosterneuburg und weiter in Richtung Tulln und Krems führt"}, {"kategorie": "", "text": "Die Klosterneuburger Straße ist eine der Hauptverkehrsstraßen in Brigittenau und diente ursprünglich als Verbindungsweg zwischen Wien und Klosterneuburg. Sie ist von einer Mischung aus Wohn- und Geschäftsbauten gesäumt. Die Gebäude entlang der Straße stammen überwiegend aus der [[Gründerzeit]] und dem frühen 20. Jahrhundert, was der Straße einen historischen und urbanen Charakter verleiht."}]'::jsonb, ''),
  ('baunhof-wiin-mitte', 'Baunhof Wiin Mitte', '', '', '', '', 'Bahnhof Wien Mitte', '[{"kategorie": "allg.", "text": "\"einer der wichtigsten Verkehrsknotenpunkte in Wien, auch \"Wien Mitte - The Mall\" genannt"}, {"kategorie": "", "text": "Er befindet sich im 3. Wiener Gemeindebezirk ([[Landstraße]]) und ist ein zentraler Umsteigepunkt für den öffentlichen Nah- und Fernverkehr"}, {"kategorie": "", "text": "Der Bahnhof Wien Mitte liegt im Herzen des 3. Bezirks, in unmittelbarer Nähe zum [[Stadtpark]] und zum [[Donaukanal]]"}, {"kategorie": "", "text": "Wien Mitte ist ein zentraler Knotenpunkt im Wiener Nahverkehrssystem. Der Bahnhof wird von mehreren S-Bahn-Linien bedient, darunter die wichtige Stammstrecke, die durch das Stadtzentrum verläuft und eine direkte Verbindung zu anderen großen Bahnhöfen wie dem [[Hauptbahnhof]] und dem [[Praterstern]] bietet"}, {"kategorie": "", "text": "Zudem ist Wien Mitte der Endpunkt des City Airport Train (CAT), einer direkten Verbindung zum Flughafen Wien-Schwechat, die eine schnelle und komfortable Anreise zum Flughafen ermöglicht"}, {"kategorie": "", "text": "Der Bahnhof wird auch von den U-Bahn-Linien U3 und U4 bedient, die eine schnelle Verbindung zu vielen wichtigen Zielen innerhalb der Stadt bieten"}, {"kategorie": "", "text": "Der Bahnhof Wien Mitte hat eine lange Geschichte, die bis ins 19. Jahrhundert zurückreicht. Ursprünglich als Terminal für die Kaiser-Ferdinands-Nordbahn erbaut, hat sich der Bahnhof im Laufe der Zeit zu einem der zentralen Verkehrsknotenpunkte Wiens entwickelt"}, {"kategorie": "", "text": "Der Bahnhof Wien Mitte wurde in den letzten Jahren umfassend modernisiert und erweitert. Das Einkaufszentrum The Mall, das direkt mit dem Bahnhof verbunden ist, bietet auf mehreren Etagen eine Vielzahl von Geschäften, Restaurants und Dienstleistungen, die den Bahnhof zu einem attraktiven Ziel für Reisende und Anwohner gleichermaßen machen."}]'::jsonb, ''),
  ('obare-donauschdrossn', 'Obare Donauschdrossn', '', '', '', '', 'Obere Donaustraße', '[{"kategorie": "allg.", "text": "\"bedeutende Verkehrsstraße in Wien, die entlang des linken (westlichen) Ufers des [[Donaukanals]] verläuft. Sie befindet sich im 2. Wiener Gemeindebezirk ([[Leopoldstadt]]) und erstreckt sich parallel zum Donaukanal von der [[Inneren]] Stadt bis in den nördlichen Teil des Bezirks\""}, {"kategorie": "", "text": "Die Obere Donaustraße hat ihren Namen von ihrer Lage entlang des Donaukanals, einem wichtigen historischen Wasserweg, der die Stadt Wien durchquert.  Die Obere Donaustraße wurde ursprünglich \"Oberer Fall\" (Fall = steiles Ufer) genannt. Die jetzige Bezeichnung geht auf das Jahr 1862 zurück"}, {"kategorie": "", "text": "Historisch gesehen war die Gegend entlang der Oberen Donaustraße ein wichtiger Knotenpunkt für den Güterverkehr, was sich in der Entwicklung der umliegenden Viertel widerspiegelt"}, {"kategorie": "", "text": "Die Obere Donaustraße bietet eine direkte Verbindung zu wichtigen Brücken über den Donaukanal, darunter die [[Augartenbrücke]], die [[Rossauerbrücke]] und die [[Friedensbrücke]]"}, {"kategorie": "", "text": "Die Straße ist eine wichtige Verbindung für den innerstädtischen Verkehr und bietet darüber hinaus auch Zugang zu mehreren kulturellen Stätten und Erholungsgebieten entlang des Kanals."}]'::jsonb, ''),
  ('untare-donauschdrossn', 'Untare Donauschdrossn', '', '', '', '', 'Untere Donaustraße', '[{"kategorie": "allg.", "text": "\"bedeutende Verkehrsstraße in Wien, die entlang des linken (westlichen) Ufers des [[Donaukanals]] verläuft\""}, {"kategorie": "", "text": "Sie befindet sich im 2. Wiener Gemeindebezirk ([[Leopoldstadt]]) und bildet zusammen mit der [[Oberen]] Donaustraße auf derselben Uferseite eine wichtige Verkehrsachse entlang des Donaukanals. Die Straße verbindet das Stadtzentrum mit den nördlichen Teilen Wiens und ist eine zentrale Route für den innerstädtischen Verkehr"}, {"kategorie": "", "text": "Die Untere Donaustraße hat ihren Namen von ihrer Lage entlang des Donaukanals, einem wichtigen historischen Wasserweg, der die Stadt Wien durchquert.  Die Untere Donaustraße wurde ursprünglich \"Unterer Fall\" (Fall = steiles Ufer) genannt. Die jetzige Bezeichnung geht auf das Jahr 1862 zurück"}, {"kategorie": "", "text": "Die Straße verläuft durch ein dicht besiedeltes urbanes Gebiet und bietet eine direkte Verbindung zu wichtigen Brücken über den Donaukanal, wie der [[Schwedenbrücke]] und der [[Marienbrücke]]."}]'::jsonb, ''),
  ('rossaua-kasean', 'Rossaua Kasean', '', '', '', '', 'Rossauer Kaserne', '[{"kategorie": "allg.", "text": "\"historische Militäranlage im 9. Wiener Gemeindebezirk ([[Alsergrund]])\""}, {"kategorie": "", "text": "Sie befindet sich an der [[Rossauer]] Lände entlang des Donaukanals und ist eine der bedeutendsten und größten Kasernen in Wien"}, {"kategorie": "", "text": "Die Kaserne wurde im 19. Jahrhundert erbaut, ursprünglich als militärische Anlage im Rahmen der umfassenden Befestigungsmaßnahmen der Stadt Wien. Die Architektur der Rossauer Kaserne ist typisch für die Militärbauten des 19. Jahrhunderts, mit einer imposanten und funktionalen Bauweise, die Stabilität und Sicherheit vermittelt. Die Außenfassade ist schlicht und robust, charakteristisch für militärische Anlagen dieser Zeit"}, {"kategorie": "", "text": "Sie diente verschiedenen militärischen Zwecken, ehe sie schließlich in den 20er Jahren des 20. Jahrhunderts der Polizei übergeben wurde"}, {"kategorie": "", "text": "Heute dient die Rossauer Kaserne als Hauptquartier der Wiener Polizei und ist eine der wichtigsten Polizeidienststellen in Wien. Sie beherbergt auch wichtige Teile der Verwaltung des Innenministeriums, das für die landesweite Polizeiarbeit verantwortlich ist."}]'::jsonb, ''),
  ('wiina-hauptfeiawoch', 'Wiina Hauptfeiawoch', '', '', '', '', 'Wiener Hauptfeuerwache', '[{"kategorie": "allg.", "text": "\"zentrale Feuerwache der Berufsfeuerwehr Wien\""}, {"kategorie": "", "text": "Die Hauptfeuerwache hat eine strategische Bedeutung, da sie für die Koordination und Leitung von Feuerwehreinsätzenzuständig ist"}, {"kategorie": "", "text": "Historisch lag die Hauptfeuerwache am Hof, heute gibt es in Wien insgesamt 12 Hauptfeuerwachen der Berufsfeuerwehr, die strategisch über das ganze Stadtgebiet verteilt sind"}, {"kategorie": "", "text": "Diese Wachen bilden das Rückgrat des städtischen Brandschutzes und des Katastrophenschutzes und stellen sicher, dass die Feuerwehr in allen Teilen der Stadt schnell und effektiv auf Notfälle reagieren kann."}]'::jsonb, ''),
  ('rossaua-bruckn', 'Rossaua Bruckn', '', '', '', '', 'Rossauer Brücke', '[{"kategorie": "allg.", "text": "Straßenbrücke in Wien, die den [[Donaukanal]] überspannt und [[die]] Rossauer Lände im 9. Bezirk ([[Alsergrund]]) mit der [[Oberen]] Donaustraße im 2. Bezirk ([[Leopoldstadt]]) verbindet"}, {"kategorie": "", "text": "Diese Lage macht sie zu einer wichtigen Verbindung für den Straßenverkehr, einschließlich Autos, Fahrräder und Fußgänger, die zwischen den beiden Bezirken verkehren. Die Brücke befindet sich in der Nähe der [[Rossauer]] Kaserne, was ihre strategische Bedeutung unterstreicht"}, {"kategorie": "", "text": "Die Rossauer Brücke wurde nach dem Stadtteil Rossau benannt, einem historischen Viertel im 9. Bezirk, das ursprünglich außerhalb der alten Stadtmauern Wiens lag. Der Name \"Rossau\" leitet sich vermutlich von den früheren Pferdeweiden (\"Rossweiden\") in diesem Gebiet ab"}, {"kategorie": "", "text": "Die erste Brücke an dieser Stelle wurde im 19. Jahrhundert gebaut, als Wien begann, seine Infrastruktur auszubauen und den Donaukanal stärker in die Stadtentwicklung einzubeziehen. Heute ist die Rossauer Brücke eine stark frequentierte Verkehrsverbindung und ein unverzichtbarer Bestandteil des Wiener Stadtverkehrs. Sie erfüllt eine wichtige Funktion, indem sie zwei zentrale Bezirke miteinander verbindet und somit den Verkehr über den Donaukanal erleichtert."}]'::jsonb, ''),
  ('nussduafa-schdrossn', 'Nussduafa Schdrossn', '', '', '', '', 'Nussdorfer Straße', '[{"kategorie": "", "text": "Die Nussdorfer Straße war ursprünglich ein wichtiger Weg, der vom damaligen Wiener Stadtrand in die ländlicheren Gebiete im Nordwesten führte"}, {"kategorie": "", "text": "Ihr Name leitet sich vom nahe gelegenen [[Nussdorf]], einem ehemaligen Vorort und heutigen Teil des 19. Wiener Bezirks (Döbling), ab, vor dem die Straße endet"}, {"kategorie": "", "text": "Entlang der Straße gibt es eine Mischung aus historischen Gebäuden aus der [[Gründerzeit]] (spätes 19. Jahrhundert) und modernen Bauten. Viele der alten Zinshäuser prägen noch heute das Erscheinungsbild der Nussdorfer Straße"}, {"kategorie": "", "text": "Eines der bekanntesten Gebäude an der Nussdorfer Straße ist das Geburtshaus von Franz Schubert (Nussdorfer Straße 54), wo der berühmte Komponist 1797 geboren wurde"}, {"kategorie": "", "text": "Seit 1912 ist das Schubert-Geburtshaus ein Museum, das Schuberts Leben und Werk dokumentiert"}, {"kategorie": "", "text": "Franz Schubert war einer der bedeutendsten Komponisten der Romantik und bekannt für seine Lieder, Symphonien, Kammermusik und Klavierwerke. Seine Werke wie die \"Unvollendete\" Sinfonie, der Liederzyklus \"Winterreise\" oder die \"Ave Maria\" zählen zu den größten Meisterwerken der klassischen Musik."}]'::jsonb, ''),
  ('liachtntoola-pfoakiachn', 'Liachtntoola Pfoakiachn', '', '', '', '', 'Lichtentaler Pfarrkirche', '[{"kategorie": "allg.", "text": "\"bedeutende katholische Kirche im 9. Wiener Gemeindebezirk ([[Alsergrund]]), offiziell bekannt als \"Pfarrkirche Lichtental, Zum Heiligen Kreuz\""}, {"kategorie": "", "text": "Sie befindet sich im historischen Stadtteil [[Lichtental]] und ist ein markantes Beispiel für den spätbarocken Kirchenbau des 18. Jahrhunderts"}, {"kategorie": "", "text": "Die Lichtentaler Pfarrkirche wurde zwischen 1712 und 1730 erbaut und ist dem Heiligen Kreuz geweiht. Der Bau der Kirche wurde von Kaiserin Elisabeth Christine, der Frau von Kaiser [[Karl]] VI., unterstützt, was zeigt, wie wichtig dieser Kirchenbau im damaligen Wien war. Die Kirche wurde nach den Plänen von Anton Ospel errichtet, einem bedeutenden Wiener Architekten, der für seine Arbeiten im barocken Stil bekannt war"}, {"kategorie": "", "text": "Das Äußere der Kirche ist von schlichter Eleganz geprägt, typisch für den spätbarocken Stil, mit einer Fassade, die durch Pilaster und ein Giebelgesims gegliedert ist. Die beiden Türme an der Vorderseite der Kirche sind ein charakteristisches Merkmal und prägen das Stadtbild von Lichtental"}, {"kategorie": "", "text": "Der Innenraum der Lichtentaler Pfarrkirche ist reich mit barocken und klassizistischen Elementen ausgestattet. Besonders hervorzuheben sind die Fresken und Altäre, die eine hohe künstlerische Qualität aufweisen. Der Hochaltar zeigt eine Darstellung der Kreuzigung Christi, ein zentrales Thema, das sich durch die gesamte künstlerische Ausstattung der Kirche zieht"}, {"kategorie": "", "text": "Auch die Seitenaltäre und die Kanzel sind bemerkenswert und zeigen eine reiche Ornamentik und kunstvolle Skulpturen. Die Kirche verfügt über eine bedeutende Orgel, die im Jahr 1831 von Johann M. Kauffmann erbaut wurde. Diese Orgel ist nicht nur ein wichtiger Bestandteil der Liturgie, sondern auch ein wertvolles historisches Instrument"}, {"kategorie": "", "text": "Hier wirkte unter anderem der berühmte österreichische Komponist Franz Schubert, der in dieser Kirche seine ersten musikalischen Erfahrungen sammelte. Schubert, der in der Nähe geboren wurde, komponierte hier einige seiner frühen Werke, und die Kirche ist heute ein wichtiger Ort des Gedenkens an diesen großen Musiker."}]'::jsonb, ''),
  ('schbittelaua-laende', 'Schbittelaua Lände', '', '', '', '', 'Spittelauer Lände', '[{"kategorie": "allg.", "text": "bedeutende Straße, die entlang des rechten Ufers des [[Donaukanals]] im 9. Wiener Gemeindebezirk ([[Alsergrund]]) verläuft"}, {"kategorie": "", "text": "Die Straße erstreckt sich von der [[Friedensbrücke]] im Westen bis zur [[Nordbrücke]] im Osten und ist Teil der Hauptverkehrsverbindung entlang des Donaukanals"}, {"kategorie": "", "text": "Der Name \"Spittelauer Lände\" leitet sich von der historischen Spittelau ab, einem Gebiet, das nach einem ehemaligen Spital (Krankenhaus) benannt wurde, das sich hier im Mittelalter befand. 1679 wurden hier sieben Baracken errichtet, um die Pestkranken von der Bevölkerung zu isolieren;  Das Gebiet wurde im Laufe der Jahrhunderte stark urbanisiert und entwickelte sich zu einem wichtigen Verkehrs- und Industriegebiet"}, {"kategorie": "", "text": "Ein markanter Punkt an der Spittelauer Lände ist die Wiener [[Müllverbrennungsanlage]] Spittelau, ein auffälliges Gebäude, das vom berühmten österreichischen Architekten Friedensreich Hundertwasser gestaltet wurde. Diese Anlage ist nicht nur für ihre Funktion im Bereich der Abfallverwertung wichtig, sondern auch ein Wahrzeichen der modernen Architektur in Wien"}, {"kategorie": "", "text": "Die Spittelauer Lände grenzt an mehrere belebte und historisch bedeutende Viertel Wiens. In der Nähe befinden sich auch mehrere bedeutende Einrichtungen, wie das Universitätszentrum [[Althanstraße]], was die Straße zu einem Knotenpunkt für Studierende und Pendler macht"}, {"kategorie": "", "text": "In den letzten Jahren hat sich die Umgebung der Spittelauer Lände zunehmend entwickelt, mit neuen Wohn- und Gewerbeprojekten, die das Stadtbild und die Nutzung der Gegend weiter verändern."}]'::jsonb, ''),
  ('wiatschoftsuni-wiin', 'Wiatschoftsuni Wiin', '', '', '', '', 'Wirtschaftsuniversität Wien', '[{"kategorie": "allg.", "text": "\"größte wirtschaftswissenschaftliche Universität in Europa und eine der führenden Hochschulen weltweit im Bereich Wirtschaft und Management\""}, {"kategorie": "", "text": "Die WU befindet sich im 2. Wiener Gemeindebezirk ([[Leopoldstadt]]), auf dem [[Messegelände]] in der Nähe des [[Praters]], und bietet ein breites Spektrum an Studiengängen und Forschungsprogrammen in den Wirtschafts-, Sozial- und Rechtswissenschaften"}, {"kategorie": "", "text": "Die Wirtschaftsuniversität Wien wurde 1898 als k.k. Exportakademie gegründet und hatte ursprünglich das Ziel, Fachkräfte für den Außenhandel auszubilden. Im Laufe der Jahre entwickelte sich die Institution weiter, wurde 1919 zur Hochschule für Welthandel umbenannt und erhielt schließlich 1975 ihren heutigen Namen Wirtschaftsuniversität Wien"}, {"kategorie": "", "text": "Seit 2013 befindet sich die WU auf einem modernen, architektonisch herausragenden Campus im 2. Bezirk, dem Campus WU. Der neue Campus wurde von international renommierten Architekten entworfen und umfasst mehrere Gebäude, darunter das ikonische Library & Learning Center (LC), das von Zaha Hadid Architects entworfen wurde. Der Campus bietet eine hochmoderne Infrastruktur mit Hörsälen, Bibliotheken, Lernräumen und sozialen Einrichtungen und ist so gestaltet, dass er interdisziplinäres Lernen und innovative Forschung unterstützt."}]'::jsonb, ''),
  ('helmut-zilk', 'Helmut Zilk', '', '', '', '', 'Helmut Zilk', '[{"kategorie": "allg.", "text": "\"bedeutender österreichischer Politiker, Journalist und Lehrer, der vor allem als Bürgermeister von Wien bekannt wurde\""}, {"kategorie": "", "text": "Zilk prägte das öffentliche Leben in Österreich über mehrere Jahrzehnte hinweg und spielte eine zentrale Rolle in der Entwicklung Wiens zu einer modernen, internationalen Metropole. Er wurde am 9. Juni 1927 in Wien geboren und verstarb ebenda am 24. Oktober 2008"}, {"kategorie": "", "text": "Nach dem Zweiten Weltkrieg, in dem er kurzzeitig als Soldat eingesetzt war, begann er seine berufliche Laufbahn als Lehrer. Er studierte Germanistik und Psychologie und arbeitete als Lehrer und später als Direktor an einer Schule in Wien"}, {"kategorie": "", "text": "In den 1950er Jahren wechselte Zilk in den Journalismus und begann eine Karriere beim österreichischen Rundfunk ([[ORF]]). Er wurde schnell zu einer bekannten Persönlichkeit im österreichischen Fernsehen und moderierte mehrere populäre Sendungen"}, {"kategorie": "", "text": "Seine politische Karriere begann Helmut Zilk in den 1970er Jahren, als er 1979 als Stadtrat für Kultur und Bildung in den Wiener Gemeinderat einzog. In dieser Funktion setzte er sich besonders für die Förderung der Kultur und Bildung in Wien ein"}, {"kategorie": "", "text": "Zilk wurde 1984 zum Bürgermeister und Landeshauptmann von Wien gewählt, eine Position, die er bis 1994 innehatte. Während seiner Amtszeit förderte er zahlreiche städtische Entwicklungsprojekte, die die Lebensqualität in Wien erheblich verbesserten. Er setzte sich besonders für den sozialen Wohnbau und den Ausbau der öffentlichen Infrastruktur ein, wodurch Wien international als Stadt mit hoher Lebensqualität anerkannt wurde"}, {"kategorie": "", "text": "Im Jahr 1993 wurde Zilk bei einem Briefbombenanschlag schwer verletzt, überlebte jedoch und setzte seine Arbeit fort. Der Anschlag war Teil einer Serie von rechtsextremen Angriffen in Österreich und führte zu einer breiten Solidaritätsbekundung aus der Bevölkerung"}, {"kategorie": "", "text": "Nach seinem Rücktritt als Bürgermeister blieb Zilk weiterhin politisch und sozial engagiert. Er setzte sich bis zu seinem Tod am 24. Oktober 2008 für verschiedene soziale und kulturelle Projekte ein. Zu seinen Ehren wurde der Helmut-Zilk-Park im [[Sonnwendviertel]] benannt, eine großzügige Grünfläche, die das Engagement Zilks für eine lebenswerte Stadt symbolisiert."}]'::jsonb, ''),
  ('per-albin-hansson-siidlung', 'Per-Albin-Hansson-Siidlung', '', '', '', '', 'Per-Albin-Hannson-Siedlung', '[{"kategorie": "allg.", "text": "große Wohnsiedlung im 10. Wiener Gemeindebezirk ([[Favoriten]])"}, {"kategorie": "", "text": "Sie ist eine der größten kommunalen Wohnanlagen der Stadt und wurde nach dem schwedischen Politiker Per Albin Hansson benannt, der von 1932 bis 1946 Ministerpräsident von Schweden war und als Begründer des schwedischen Wohlfahrtsstaates gilt"}, {"kategorie": "", "text": "Die Per-Albin-Hansson-Siedlung wurde in mehreren Bauphasen errichtet, die sich von den 1940er Jahren bis in die 1970er Jahre erstreckten. Der erste Teil der Siedlung, die sogenannte Per-Albin-Hansson-Siedlung Nord, wurde zwischen 1947 und 1951 erbaut. Dies geschah im Rahmen des Wiederaufbaus nach dem Zweiten Weltkrieg, als großer Wohnraumbedarf bestand"}, {"kategorie": "", "text": "Die Wohngebäude in der Siedlung sind meist fünf bis sechsstöckig und wurden in einem schlichten, funktionalen Stil errichtet. Die Siedlung umfasst mehrere tausend Wohneinheiten, die vor allem für Familien mit niedrigem Einkommen gedacht sind"}, {"kategorie": "", "text": "Die Per-Albin-Hansson-Siedlung ist ein bedeutendes Beispiel für den sozialen Wohnbau in Wien, der seit den 1920er Jahren eine zentrale Rolle in der Stadtplanung spielt"}, {"kategorie": "", "text": "Die Siedlung bietet ihren Bewohnern nicht nur Wohnraum, sondern auch eine umfassende Infrastruktur. Es gibt Schulen, Kindergärten, Sporteinrichtungen, Einkaufszentren und Gesundheitsdienste in unmittelbarer Nähe."}]'::jsonb, ''),
  ('rennbaunweg-siidlung', 'Rennbaunweg-Siidlung', '', '', '', '', 'Rennbahnwegsiedlung', '[{"kategorie": "allg.", "text": "große Wohnsiedlung im 22. Wiener Gemeindebezirk ([[Donaustadt]])"}, {"kategorie": "", "text": "Sie ist eine der größten [[Gemeindebausiedlungen]] Wiens und wurde zwischen 1973 und 1980 erbaut, als Wien eine stark wachsende Bevölkerung hatte und dringender Bedarf an leistbarem Wohnraum bestand"}, {"kategorie": "", "text": "Die Siedlung wurde auf dem ehemaligen Gelände einer Pferderennbahn errichtet, was ihr den Namen \"Rennbahnwegsiedlung\" gab"}, {"kategorie": "", "text": "Die Rennbahnwegsiedlung besteht aus mehreren Wohnblöcken, die zwischen vier und sechzehn Stockwerke hoch sind. Insgesamt umfasst die Siedlung mehr als 6.000 Wohneinheiten, was sie zu einer der größten Wohnanlagen Wiens macht. Die Architektur der Siedlung ist funktional und für die damalige Zeit typisch: Beton, klare Linien und große Wohnblöcke dominieren das Bild. Zwischen den Wohnblöcken gibt es weitläufige, parkähnliche Flächen, Spielplätze und Spazierwege"}, {"kategorie": "", "text": "Trotz ihrer Größe und Dichte hat die Siedlung eine stabile soziale Struktur entwickelt und gilt als lebendiges Wohnviertel mit einer vielfältigen Bewohnerstruktur."}]'::jsonb, ''),
  ('simmaringa-haad', 'Simmaringa Haad', '', '', '', '', 'Simmeringer Haide', '[{"kategorie": "allg.", "text": "\"historische Landschaft im 11. Wiener Gemeindebezirk ([[Simmering]])\""}, {"kategorie": "", "text": "Die Simmeringer Haide war ursprünglich ein ausgedehntes, weitgehend unbewohntes Areal, das sich im Südosten Wiens erstreckte. In früheren Zeiten bestand die Haide aus Grasland, das für landwirtschaftliche Zwecke genutzt wurde, sowie aus sumpfigen Bereichen. Aufgrund ihrer Lage am Rand der Stadt war sie lange Zeit kaum besiedelt und diente unter anderem als Weideland"}, {"kategorie": "", "text": "Sie reicht heute von Simmering nur bis an den [[Donaukanal]], der sie nunmehr vom [[Freudenauer]] Rennplatz trennt"}, {"kategorie": "", "text": "Die Simmeringer Haide erlangte historische Bedeutung durch die Schlacht am Kahlenberg 1683, als während der Zweiten Wiener Türkenbelagerung Truppen der Osmanen hier lagerten. Die offene Ebene bot ideale Bedingungen für das Aufstellen von Heeren, was die Haide zu einem strategischen Ort in der militärischen Geschichte Wiens machte. Am 14. August 1718 fanden auf der Simmeringer Haide Feierlichkeiten für den ersten osmanischen Gesandten Ibrahim Pascha statt"}, {"kategorie": "", "text": "Im 19. und frühen 20. Jahrhundert begann die Urbanisierung des Gebiets. Mit dem Ausbau von Industrieanlagen und der zunehmenden Bebauung von Simmering wandelte sich das Erscheinungsbild der Simmeringer Haide grundlegend. Große Teile des ursprünglichen Gebietes wurden nach und nach in die städtische Infrastruktur integriert"}, {"kategorie": "", "text": "Mit der fortschreitenden Urbanisierung ist der Großteil der ursprünglichen Haide verschwunden, doch der Name bleibt ein wichtiger Teil des historischen Erbes und der Identität Simmerings."}]'::jsonb, ''),
  ('schloss-neigebeide', 'Schloss Neigebeide', '', '', '', '', 'Schloss Neugebäude', '[{"kategorie": "allg.", "text": "historisch bedeutendes Areal im 11. Wiener Gemeindebezirk ([[Simmering]])"}, {"kategorie": "", "text": "Das Schloss Neugebäude wurde zwischen 1569 und 1573 unter Kaiser [[Maximilian]] II. errichtet und gilt als eines der bedeutendsten Bauwerke der Spätrenaissance in Österreich. Es wurde auf einem Gelände errichtet, das ursprünglich Teil eines Jagdgebiets war, und diente Kaiser Maximilian II. als repräsentative Sommerresidenz"}, {"kategorie": "", "text": "Trotz seiner prachtvollen Bauweise und Bedeutung wurde das Schloss Neugebäude bereits im 17. Jahrhundert zunehmend vernachlässigt, insbesondere nach dem Tod von Maximilian II. Während der Türkenbelagerung von 1683 diente es als Militärlager und erlitt schwere Schäden"}, {"kategorie": "", "text": "In den folgenden Jahrhunderten wurde das Schloss teilweise abgetragen, und das Baumaterial wurde für andere Bauprojekte in Wien verwendet, unter anderem für den Bau des Schlosses [[Schönbrunn]]. Der ursprüngliche Prunk des Schlosses Neugebäude ging somit verloren, und das Areal verfiel allmählich zu einer Ruine"}, {"kategorie": "", "text": "Heute sind nur noch Teile der ursprünglichen Anlage erhalten, darunter einige Mauern und Fundamente. Die erhaltenen Reste des Schlosses Neugebäude stehen unter Denkmalschutz und werden als Veranstaltungsort genutzt. Im Sommer finden hier Konzerte, Open-Air-Kinos und verschiedene kulturelle Veranstaltungen statt, die das historische Ambiente des Ortes nutzen."}]'::jsonb, ''),
  ('oidmaunnsduafa-schdrossn', 'Oidmaunnsduafa Schdrossn', '', '', '', '', 'Altmannsdorfer Straße', '[{"kategorie": "allg.", "text": "wichtige Verkehrsader in Wien, die den 12. Wiener Gemeindebezirk ([[Meidling]]) durchquert und als zentrale Verbindungsstraße im Südwesten der Stadt fungiert"}, {"kategorie": "", "text": "Sie verläuft von der [[Breitenfurter]] Straße im Westen bis zur [[Triester]] Straße und lenkt den Verkehr von den südlichen und westlichen Vororten Wiens in Richtung Innenstadt und zur [[A]]23 ([[Südosttangente]]) lenkt"}, {"kategorie": "", "text": "Sie verbindet den Bereich des [[Wienerwaldes]] und der Randbezirke mit zentraleren Stadtteilen und ist sowohl für den Individualverkehr als auch für den öffentlichen Verkehr von großer Bedeutung"}, {"kategorie": "", "text": "Die Altmannsdorfer Straße hat, ähnlich wie der benachbarte Stadtteil [[Altmannsdorf]], eine lange Geschichte. Ursprünglich war sie eine Verbindungsstraße zwischen den Dörfern Altmannsdorf und [[Hetzendorf]] und wurde erst mit der Erweiterung Wiens zu einer wichtigen Verkehrsachse ausgebaut. Sie hat sich im Laufe der Zeit von einer Landstraße zu einer hochfrequentierten Durchzugsstraße entwickelt, die heute eine zentrale Rolle im Verkehrsnetz des 12. Bezirks spielt."}]'::jsonb, ''),
  ('oidmaunnsduafa-pfoakiachn-sankt-oswoid', 'Oidmaunnsduafa Pfoakiachn Sankt Oswoid', '', '', '', '', 'Altmannsdorfer Pfarrkirche Sankt Oswald', '[{"kategorie": "allg.", "text": "\"bedeutendes religiöses und historisches Bauwerk im Stadtteil [[Altmannsdorf]] im 12. Wiener Gemeindebezirk ([[Meidling]]), oft einfach als \"Pfarrkirche St. Oswald\" bezeichnet"}, {"kategorie": "", "text": "Sie ist dem heiligen Oswald, einem frühmittelalterlichen König von Northumbria (heutiges England), geweiht, der im 7. Jahrhundert als christlicher Märtyrer verehrt wurde. Die Kirche steht im Zentrum des alten Dorfkerns von Altmannsdorf und ist ein prägendes Element des historischen Ortsbildes"}, {"kategorie": "", "text": "Bereits im 13. Jahrhundert wird eine Kapelle in Altmannsdorf erwähnt, die vermutlich der Vorläufer der heutigen Kirche war"}, {"kategorie": "", "text": "Die Kirche, wie sie heute besteht, stammt größtenteils aus dem 18. Jahrhundert und ist ist ein barocker Sakralbau, der sich durch schlichte Eleganz und harmonische Proportionen auszeichnet. Die Fassade ist typisch für die Zeit des Hochbarock und zeigt klassische Merkmale wie Pilaster, Rundbogenfenster und ein einfaches Giebelfeld:  5. Sehenswert ist der Hochaltar, der das zentrale Kunstwerk im Kirchenraum darstellt. Auf dem Altarbild ist der heilige Oswald dargestellt, der Namenspatron der Kirche. Die Seitenaltäre und einige Heiligenfiguren aus der Barockzeit ergänzen die sakrale Ausstattung"}, {"kategorie": "", "text": "Die Kirche besitzt zudem einen einfachen Kirchturm, der das Stadtbild von Altmannsdorf prägt. Im Laufe der Jahrhunderte wurden sowohl das Äußere als auch das Innere der Kirche mehrfach renoviert, wobei der ursprüngliche Barockcharakter weitgehend erhalten blieb."}]'::jsonb, ''),
  ('heamann-leopoidi-park', 'Heamann-Leopoidi-Park', '', '', '', '', 'Hermann-Leopoldi-Park', '[{"kategorie": "allg.", "text": "\"Grünanlage im dicht bebauten Stadtteil [[Altmannsdorf]], unweit der [[Altmannsdorfer]] Straße im 12. Wiener Gemeindebezirk ([[Meidling]])\""}, {"kategorie": "", "text": "Der Park wurde zu Ehren von Hermann Leopoldi (1888–1959) benannt, einem der bekanntesten Wiener Komponisten und Unterhaltungskünstler des 20. Jahrhunderts. Leopoldi war insbesondere für seine humorvollen Lieder und Chansons bekannt, die auch heute noch Teil der Wiener Musikkultur sind ["}, {"kategorie": "", "text": "Der Hermann-Leopoldi-Park ist eine beliebte Grünfläche im 12. Wiener Gemeindebezirk, die den Anwohnern von Altmannsdorf und Meidling eine wertvolle Möglichkeit zur Erholung und Freizeitgestaltung bietet. Mit seinen Spielplätzen, Sportmöglichkeiten und gepflegten Grünanlagen ist er ein wichtiger Treffpunkt und bietet sowohl Raum für Aktivitäten als auch Ruhe im sonst belebten Stadtteil."}]'::jsonb, ''),
  ('wiinabeag-city', 'Wiinabeag City', '', '', '', '', 'Wienerberg City', '[{"kategorie": "allg.", "text": "modernes Stadtentwicklungsgebiet im Süden von Wien, das sich im 10. Wiener Gemeindebezirk ([[Favoriten]]) befindet"}, {"kategorie": "", "text": "Es wurde in den letzten Jahrzehnten auf dem ehemaligen Ziegelwerksgelände des Wienerbergs errichtet und ist heute ein dynamisches Viertel mit einem Mix aus Bürogebäuden, Wohnanlagen und Freizeitmöglichkeiten. Wienerberg City zeichnet sich durch seine modernen Hochhäuser, insbesondere die markanten Twin Towers, und seine zentrale Rolle als Geschäfts- und Wohnviertel aus"}, {"kategorie": "hist.", "text": "Das Gebiet des heutigen Wienerberg City war ursprünglich ein wichtiges Industrieareal, auf dem bis ins 20. Jahrhundert hinein die bekannten Wienerberger Ziegelwerke betrieben wurden. Diese Fabriken lieferten die Baumaterialien für viele der monumentalen Gebäude, die im späten 19. und frühen 20. Jahrhundert in Wien errichtet wurden. Nach dem Ende der Ziegelproduktion wurde das Gelände rekultiviert und begann, sich städtisch zu entwickeln"}, {"kategorie": "", "text": "Das markanteste Bauwerk des Viertels sind die Twin Towers, zwei miteinander verbundene Hochhäuser, die als Wahrzeichen von Wienerberg City gelten. Diese Gebäude sind mit einer Höhe von 138 Metern eines der höchsten in Wien und beherbergen zahlreiche Büros internationaler Unternehmen sowie Gastronomieeinrichtungen."}]'::jsonb, ''),
  ('braadnfuata-schdrossn', 'Braadnfuata Schdrossn', '', '', '', '', 'Breitenfurter Straße', '[{"kategorie": "allg.", "text": "bedeutende Verkehrsader im Süden von Wien, die vom 12. Wiener Gemeindebezirk ([[Meidling]]) bis in den 23. Bezirk ([[Liesing]]) bzw. den Stadtteil [[Kalksburg]] verläuft. Sie führt von der Stadtgrenze Wiens in Richtung der benachbarten Gemeinde Breitenfurt in Niederösterreich, nach der sie auch benannt ist"}, {"kategorie": "", "text": "Die Straße, die heute als Breitenfurter Straße bekannt ist, hatte im Mittelalter den Namen Liesinger Weg und wurde 1593 einfach als \"Die Straße\" bezeichnet. Später hieß sie \"Ordinari Straße von Wien nach Atzgersdorf\" und dann \"Breitenfurther Waldämtliche Straße\", benannt nach dem Ort Breitenfurt"}, {"kategorie": "", "text": "Heute ist die Breitenfurter Straße eine stark frequentierte Verkehrsroute, die als Hauptverbindung zwischen Wien und den südwestlich gelegenen Vororten und Gemeinden dient. Sie ist eine der wichtigsten Ausfallstraßen in den [[Wienerwald]] und ins niederösterreichische Umland"}, {"kategorie": "", "text": "Die Breitenfurter Straße hat eine lange Geschichte und diente bereits vor Jahrhunderten als Verbindungsweg zwischen Wien und den westlich gelegenen Wienerwaldgemeinden. Ursprünglich war sie eine einfache Landstraße, die mit der zunehmenden Besiedlung und dem Ausbau der Vororte zu einer wichtigen Verkehrsader ausgebaut wurde."}]'::jsonb, ''),
  ('baunhof-liising', 'Baunhof Liising', '', '', '', '', 'Bahnhof Liesing', '[{"kategorie": "allg.", "text": "bedeutender Verkehrsknotenpunkt im 23. Wiener Gemeindebezirk ([[Liesing]]) und einer der wichtigsten Bahnhöfe im Süden Wiens"}, {"kategorie": "", "text": "Der Bahnhof dient als wichtiger Knotenpunkt für den Nah- und Regionalverkehr und verbindet den südlichen Teil Wiens mit der Innenstadt sowie mit Niederösterreich und dem übrigen Österreich"}, {"kategorie": "", "text": "Durch seine Lage im Zentrum des Bezirks ist der Bahnhof auch ein wirtschaftlich bedeutender Standort, der die Entwicklung des Stadtteils maßgeblich prägt"}, {"kategorie": "hist.", "text": "Der Bahnhof Liesing blickt auf eine lange Geschichte zurück, da er bereits im 19. Jahrhundert im Zuge des Ausbaus der Südbahnlinie errichtet wurde. Diese Bahnstrecke war von großer Bedeutung für die industrielle Entwicklung im Süden Wiens und Niederösterreichs, und der Bahnhof Liesing spielte dabei eine zentrale Rolle als Umschlagplatz für Güter und Personenverkehr."}]'::jsonb, ''),
  ('baunhof-meidling', 'Baunhof Meidling', '', '', '', '', 'Bahnhof Meidling', '[{"kategorie": "allg.", "text": "\"einer der wichtigsten Verkehrsknotenpunkte in Wien, der im 12. Wiener Gemeindebezirk ([[Meidling]]) liegt\""}, {"kategorie": "", "text": "Er erstreckt sich entlang der [[Eichenstraße]] und dient sowohl als zentraler Umsteigepunkt für den öffentlichen Nahverkehr als auch als bedeutender Fernverkehrsbahnhof, von dem aus Züge in verschiedene Teile Österreichs und ins Ausland verkehren. Der Bahnhof Meidling ist nach dem [[Wiener]] Hauptbahnhof der zweitwichtigste Bahnhof der Stadt und spielt eine wesentliche Rolle im täglichen Pendlerverkehr"}, {"kategorie": "hist.", "text": "Der Bahnhof Meidling hat eine lange Geschichte, die bis ins 19. Jahrhundert zurückreicht. Ursprünglich als Bahnhof für den Stadtteil Meidling angelegt, hat er sich über die Jahrzehnte mit dem Wachstum Wiens und dem Ausbau des Eisenbahnnetzes zu einem der wichtigsten Bahnhöfe der Stadt entwickelt. Besonders seit dem Umbau und der Modernisierung in den 2000er-Jahren hat der Bahnhof Meidling an Bedeutung gewonnen, insbesondere nach der Eröffnung des Wiener Hauptbahnhofs 2014, da Meidling als Umsteigebahnhof für viele Fernverkehrszüge fungiert."}]'::jsonb, '')
